#!/usr/bin/env python3
"""
buildium_report.py -- Generate a Buildium financial report (Excel + PDF) for
a single association.

For this first test we focus on the general_ledger report type. The other
report types (income_statement, balance_sheet, trial_balance) are stubbed;
they'll be filled in after we confirm the pipeline works end-to-end.

Credentials are read from .env next to this script (BUILDIUM_CLIENT_ID /
BUILDIUM_CLIENT_SECRET) or from the process environment.

Outputs go to ./out/.

Usage:
    py -3 buildium_report.py \
        --building "571 Hudson Street Apartment Corp" \
        --association-id 170555 \
        --report-type general_ledger \
        --start-date 2025-01-01 \
        --end-date 2025-12-31

All CLI args default to the 571 Hudson 2025 general ledger test case, so a
bare `py -3 buildium_report.py` run does the smoke test.
"""
from __future__ import annotations

import argparse
import json
import os
import sys
from collections import defaultdict
from datetime import date, datetime, timedelta
from decimal import Decimal, InvalidOperation
from pathlib import Path
from typing import Any

import requests
from dotenv import load_dotenv
from openpyxl import Workbook
from openpyxl.styles import Alignment, Font, PatternFill
from openpyxl.utils import get_column_letter
from reportlab.lib import colors
from reportlab.lib.pagesizes import landscape, letter
from reportlab.lib.styles import ParagraphStyle, getSampleStyleSheet
from reportlab.lib.units import inch
from reportlab.platypus import (
    Image,
    Paragraph,
    SimpleDocTemplate,
    Spacer,
    Table,
    TableStyle,
)

# Daisy brand palette used throughout the PDF reports.
DAISY_GREEN = "#1B4332"       # hunter green (headers, sections)
DAISY_CREAM = "#F5F5F0"       # light cream (alternating row shading)

_CANONICAL_BUILDIUM_BASE = "https://api.buildium.com/v1"
# Mutable at runtime via --api-base-url. When pointed at the public Buildium
# API (the default), the script makes direct GETs with x-buildium-* headers.
# When pointed at a proxy URL (e.g. Vercel /api/buildium-proxy), the script
# wraps each GET into a POST {method, path, params} so the proxy can hold
# the credentials server-side and the script never needs to know them.
BUILDIUM_BASE = _CANONICAL_BUILDIUM_BASE
_PROXY_MODE = False
SCRIPT_DIR = Path(__file__).parent
OUT_DIR = SCRIPT_DIR / "out"
DAISY_LOGO_PATH = SCRIPT_DIR / "assets" / "daisy-logo.png"
