def _materialize_daisy_logo_if_missing() -> Path:
    """If DAISY_LOGO_PATH isn't on disk (routine-runner case), decode the
    embedded base64 blob into a tmp file and return that path. Otherwise
    return DAISY_LOGO_PATH unchanged."""
    import base64
    import tempfile
    if DAISY_LOGO_PATH.exists():
        return DAISY_LOGO_PATH
    tmp_dir = Path(tempfile.gettempdir())
    out = tmp_dir / "daisy-logo.png"
    if not out.exists():
        out.write_bytes(base64.b64decode(_DAISY_LOGO_B64))
    return out


# Resolve once at module load. Local dev: DAISY_LOGO_PATH stays pointed at
# the assets/ file. Routine runner: DAISY_LOGO_PATH is rewritten to the tmp
# file so every downstream reader (existence check, Image flowable) works
# without further changes.
DAISY_LOGO_PATH = _materialize_daisy_logo_if_missing()


