# Accounting basis used for every Buildium API call that respects it (GL
# transactions, GL balances) and surfaced in every report's title block. Set
# from --basis at the top of main(); defaults to Cash because that's how
# most NYC co-op boards review their financials. Override with
# --basis Accrual when a CPA explicitly asks for accrual reporting.
ACCOUNTING_BASIS_CHOICES = ("Cash", "Accrual")
_BASIS = "Cash"


# --------------------------------------------------------------------------
# HTTP
# --------------------------------------------------------------------------

def load_credentials() -> dict[str, str]:
    """
    Build the Buildium auth header dict.

    In proxy mode (--api-base-url pointed at the Vercel proxy), the proxy
    holds the credentials server-side, so the local script doesn't need
    them. We return an empty dict so callers don't have to special-case
    this branch — the headers are simply not forwarded by _get_with_retries
    when _PROXY_MODE is True (the proxy adds them).
    """
    if _PROXY_MODE:
        return {"Accept": "application/json"}
    load_dotenv(SCRIPT_DIR / ".env")
    cid = os.environ.get("BUILDIUM_CLIENT_ID")
    cs = os.environ.get("BUILDIUM_CLIENT_SECRET")
    if not cid or not cs:
        sys.exit(
            "ERROR: BUILDIUM_CLIENT_ID and BUILDIUM_CLIENT_SECRET must be set "
            "(in .env next to this script or in the process environment), "
            "or run with --api-base-url <proxy-url> to use a server-side proxy."
        )
    return {
        "x-buildium-client-id": cid,
        "x-buildium-client-secret": cs,
        "Accept": "application/json",
    }


def _get_with_retries(
    url: str, headers: dict, params: dict, label: str, max_retries: int = 3
) -> requests.Response:
    """
    GET with retries on transient errors (connection, 502/503/504). Each
    retry waits progressively longer. Returns the response regardless of
    status code -- caller decides what counts as success.

    In proxy mode (BUILDIUM_BASE points at a Vercel proxy URL rather than
    the canonical Buildium API), the GET is repackaged as a POST with body
    {method, path, params} per the proxy's contract. The Buildium auth
    headers are NOT forwarded — the proxy holds them server-side and adds
    them on the way out.
    """
    import time

    last_exc: Exception | None = None
    for attempt in range(1, max_retries + 1):
        try:
            if _PROXY_MODE:
                # Strip the proxy base off the URL to recover the upstream
                # Buildium path, then POST {method, path, params} to the proxy.
                if url.startswith(BUILDIUM_BASE):
                    upstream_path = url[len(BUILDIUM_BASE):].lstrip("/")
                else:
                    # Defensive — if a caller built a URL by other means,
                    # treat the whole url as the path. Should not happen.
                    upstream_path = url.lstrip("/")
                proxy_body = {
                    "method": "GET",
                    "path": upstream_path,
                    "params": params or {},
                }
                r = requests.post(
                    BUILDIUM_BASE,
                    json=proxy_body,
                    headers={"Accept": "application/json"},
                    timeout=180,
                )
            else:
                r = requests.get(url, headers=headers, params=params, timeout=180)
            if r.status_code in (429, 502, 503, 504) and attempt < max_retries:
                # 429 (rate limit) needs a longer cool-down than transient 5xx.
                retry_after = r.headers.get("Retry-After")
                if retry_after and retry_after.isdigit():
                    wait = int(retry_after)
                elif r.status_code == 429:
                    wait = 10 * attempt
                else:
                    wait = 2 * attempt
                print(
                    f"    [{label}] HTTP {r.status_code}, retrying in {wait}s "
                    f"(attempt {attempt}/{max_retries})",
                    flush=True,
                )
                time.sleep(wait)
                continue
            return r
        except (requests.ConnectionError, requests.Timeout) as e:
            last_exc = e
            if attempt < max_retries:
                wait = 2 * attempt
                print(
                    f"    [{label}] {type(e).__name__}, retrying in {wait}s "
                    f"(attempt {attempt}/{max_retries})",
                    flush=True,
                )
                time.sleep(wait)
                continue
            raise
    raise RuntimeError(f"Unreachable: {last_exc}")


def paginated_get(url: str, headers: dict, params: dict, label: str) -> list[dict]:
    """GET a Buildium list endpoint with offset pagination. Prints progress."""
    all_rows: list[dict] = []
    limit = 1000
    offset = 0
    pages = 0
    while True:
        pages += 1
        p = dict(params, limit=limit, offset=offset)
        r = _get_with_retries(url, headers, p, label)
        if not r.ok:
            sys.exit(
                f"ERROR: {label} HTTP {r.status_code}\n"
                f"URL: {r.url}\n"
                f"Body: {r.text[:1500]}"
            )
        try:
            batch = r.json()
        except ValueError:
            sys.exit(f"ERROR: {label} returned non-JSON:\n{r.text[:1500]}")
        if not isinstance(batch, list):
            sys.exit(
                f"ERROR: {label} returned non-list "
                f"({type(batch).__name__}):\n{json.dumps(batch)[:1500]}"
            )
        all_rows.extend(batch)
        print(
            f"  [{label} page {pages}] +{len(batch)} rows "
            f"(total {len(all_rows)})",
            flush=True,
        )
        if len(batch) < limit:
            break
        offset += limit
        if pages > 100:
            sys.exit(f"Safety stop: {label} exceeded 100 pages")
    return all_rows


def fetch_gl_accounts(headers: dict) -> list[dict]:
    print("Fetching chart of accounts...", flush=True)
    return paginated_get(
        f"{BUILDIUM_BASE}/glaccounts",
        headers,
        params={},
        label="glaccounts",
    )


def fetch_association(headers: dict, association_id: int) -> dict:
    """Look up a single association record."""
    r = _get_with_retries(
        f"{BUILDIUM_BASE}/associations/{association_id}",
        headers,
        params={},
        label=f"association {association_id}",
    )
    if not r.ok:
        sys.exit(
            f"ERROR: association {association_id} lookup failed: "
            f"HTTP {r.status_code}\n{r.text[:500]}"
        )
    return r.json()


def derive_building_code(association_name: str) -> str | None:
    """
    Daisy's associations are named like 'NYC107P - 571 Hudson Street'. The
    building code (e.g. 'NYC107P') prefixes every GL account that belongs to
    the building, so we can use it to find the building's own bank accounts.

    If the association name doesn't follow the convention we return None and
    the caller falls back to another strategy.
    """
    if " - " in association_name:
        code = association_name.split(" - ", 1)[0].strip()
        if code:
            return code
    return None


def find_building_accounts(
    all_accounts_flat: dict[int, dict],
    building_code: str | None,
    building_name: str,
) -> list[int]:
    """
    Find the set of GL account ids that are specific to one building. We
    look for the building code (e.g. 'NYC107P') or the building name
    ('571 Hudson Street') appearing in an account's Name.
    """
    code_upper = building_code.upper() if building_code else None
    name_upper = building_name.upper()

    matches: list[int] = []
    for aid, a in all_accounts_flat.items():
        nm = (a.get("Name") or "").upper()
        if code_upper and code_upper in nm:
            matches.append(aid)
        elif name_upper and name_upper in nm:
            matches.append(aid)
    return sorted(matches)


def _month_windows(start_d: date, end_d: date) -> list[tuple[date, date]]:
    """Split [start_d, end_d] inclusive into one tuple per calendar month."""
    from datetime import timedelta
    windows = []
    cur = start_d.replace(day=1)
    while cur <= end_d:
        if cur.month == 12:
            next_first = date(cur.year + 1, 1, 1)
        else:
            next_first = date(cur.year, cur.month + 1, 1)
        ws = max(cur, start_d)
        we = min(next_first - timedelta(days=1), end_d)
        windows.append((ws, we))
        cur = next_first
    return windows


def fetch_transactions(
    headers: dict,
    start_date: str,
    end_date: str,
    building_account_ids: list[int],
    pl_account_ids: list[int] | None = None,
    association_id: int | None = None,
) -> list[dict]:
    """
    Fetch GL transactions for a specific building, in two passes:

    1. Primary: building-specific accounts (NYC107P bank/escrow IDs) for
       the full date range. Captures every transaction that touches the
       building's own dedicated accounts.

    2. Secondary (optional): all Income + Expense account IDs from the
       chart of accounts, chunked by calendar month (because full-year
       company-wide P&L queries 504 timeout). Each returned transaction
       is filtered client-side to keep only those with at least one
       Journal line tagged AccountingEntity.Id == association_id.

       This catches activity on SHARED P&L accounts (Maintenance Income,
       Property Taxes, Capital Assessment, etc.) that the primary pass
       misses because shared accounts aren't named with a building prefix.

    Both passes are deduped by transaction Id (primary wins on conflict
    since it's more authoritative for accounts the building actually owns).

    Buildium quirks worth knowing:
      - accountingentityids on this endpoint is silently ignored, which is
        why the secondary pass has to filter client-side.
      - 50+ accounts × full year reliably 504-times out, so we chunk by
        month for the secondary pass even if the account list is small.
    """
    if not building_account_ids:
        sys.exit(
            "ERROR: no building-specific GL accounts were found -- cannot "
            "fetch transactions without a filter."
        )

    # --- Primary pass: building-specific accounts, full date range ---
    print(
        f"Fetching GL transactions from {start_date} to {end_date} "
        f"(basis={_BASIS})\n"
        f"  primary filter: {len(building_account_ids)} building-specific GL accounts "
        f"({', '.join(str(x) for x in building_account_ids)})",
        flush=True,
    )
    primary = paginated_get(
        f"{BUILDIUM_BASE}/generalledger/transactions",
        headers,
        params={
            "startdate": start_date,
            "enddate": end_date,
            "glaccountids": ",".join(str(x) for x in building_account_ids),
            "accountingbasis": _BASIS,
        },
        label="primary-txns",
    )
    by_id: dict[int, dict] = {
        t["Id"]: t for t in primary if t.get("Id") is not None
    }

    # --- Secondary pass: shared P&L coverage ---
    if pl_account_ids and association_id is not None:
        from datetime import datetime as _dt
        start_d = _dt.strptime(start_date, "%Y-%m-%d").date()
        end_d = _dt.strptime(end_date, "%Y-%m-%d").date()
        windows = _month_windows(start_d, end_d)
        pl_csv = ",".join(str(x) for x in pl_account_ids)
        print(
            f"  secondary filter: {len(pl_account_ids)} P&L account ids "
            f"x {len(windows)} month windows (catches shared-account activity)",
            flush=True,
        )
        added = 0
        for ws, we in windows:
            month_txns = paginated_get(
                f"{BUILDIUM_BASE}/generalledger/transactions",
                headers,
                params={
                    "startdate": ws.isoformat(),
                    "enddate": we.isoformat(),
                    "glaccountids": pl_csv,
                    "accountingbasis": _BASIS,
                },
                label=f"pl-txns({ws:%Y-%m})",
            )
            for t in month_txns:
                tid = t.get("Id")
                if tid is None or tid in by_id:
                    continue
                # Keep only if at least one line is tagged to our association
                lines = (t.get("Journal") or {}).get("Lines") or []
                if any(
                    (line.get("AccountingEntity") or {}).get("Id") == association_id
                    for line in lines
                ):
                    by_id[tid] = t
                    added += 1
        print(
            f"  secondary pass added {added} txns "
            f"(primary {len(primary)}, total {len(by_id)})",
            flush=True,
        )

    return list(by_id.values())


