def fetch_gl_balances(
    headers: dict, as_of_date: str, association_id: int,
    basis: str | None = None,
) -> dict[int, Decimal]:
    """
    Fetch every GL account's balance as-of a given date, filtered client-side
    to ONE association.

    Buildium's `/v1/glaccounts/balances` endpoint returns company-wide rows,
    each with `AccountingEntityBalances[*]` listing per-association breakdowns.
    We paginate through the full set, then for each row we pick out the entry
    whose AccountingEntity.Id matches `association_id`.

    Quirks worth knowing:
      - Query params MUST be lowercase (`accountingbasis`, not `AccountingBasis`)
        or you get a 422.
      - Zero-balance accounts are NOT returned; callers should treat missing
        keys as ZERO.
      - The endpoint ignores any `accountingentityids` / `associationids`
        filter you send, so the client-side filter is mandatory.

    Returns {gl_account_id: balance_for_association} as a dict of Decimals.
    Sign convention: Buildium returns POSITIVE values for normal-direction
    balances (Asset debit-normal positive, Liability credit-normal positive).
    """
    actual_basis = basis if basis else _BASIS
    all_rows = paginated_get(
        f"{BUILDIUM_BASE}/glaccounts/balances",
        headers,
        {"accountingbasis": actual_basis, "asofdate": as_of_date},
        f"gl-balances({actual_basis},{as_of_date})",
    )
    result: dict[int, Decimal] = {}
    for row in all_rows:
        gl = row.get("GLAccount") or {}
        gl_id = gl.get("Id")
        if gl_id is None:
            continue
        for ae_entry in row.get("AccountingEntityBalances") or []:
            ae = ae_entry.get("AccountingEntity") or {}
            if ae.get("Id") == association_id:
                result[gl_id] = _to_decimal(ae_entry.get("Balance"))
                break
    return result


def fetch_gl_balances_period(
    headers: dict, start_date: str, end_date: str, association_id: int,
) -> dict[int, Decimal]:
    """
    Compute each account's CHANGE in balance over the period, using two calls
    to the GL balance endpoint (as-of day-before-start and as-of end-date).
    This is what callers should compare to 'period activity' numbers computed
    from transaction sums.

    For a building that onboarded after start_date, the opening balance is
    effectively $0 and period-activity == end-balance. For older buildings
    both endpoints return real numbers and the subtraction matters.
    """
    from datetime import timedelta
    start_d = datetime.strptime(start_date, "%Y-%m-%d").date()
    opening_as_of = (start_d - timedelta(days=1)).isoformat()

    opening = fetch_gl_balances(headers, opening_as_of, association_id)
    closing = fetch_gl_balances(headers, end_date, association_id)

    # Build a period-activity dict using closing - opening. Include every
    # account that appears in either snapshot so we don't miss accounts that
    # were only active in one half of the period.
    all_ids = set(opening.keys()) | set(closing.keys())
    return {
        aid: closing.get(aid, ZERO) - opening.get(aid, ZERO)
        for aid in all_ids
    }


# --------------------------------------------------------------------------
# Account flattening
# --------------------------------------------------------------------------

def flatten_accounts(accounts: list[dict]) -> dict[int, dict]:
    """
    Recursively walk SubAccounts and return a {Id: account_record} map where
    every account (parent and leaf) appears exactly once. A `_depth` field is
    attached so callers can indent hierarchically.
    """
    out: dict[int, dict] = {}

    def walk(a: dict, depth: int = 0) -> None:
        aid = a.get("Id")
        if aid is None:
            return
        rec = {
            "Id": aid,
            "AccountNumber": a.get("AccountNumber") or "",
            "Name": a.get("Name") or "",
            "Type": a.get("Type") or "",
            "SubType": a.get("SubType") or "",
            "ParentGLAccountId": a.get("ParentGLAccountId"),
            "IsActive": a.get("IsActive", True),
            "_depth": depth,
        }
        if aid not in out:
            out[aid] = rec
        for s in a.get("SubAccounts") or []:
            walk(s, depth + 1)

    for a in accounts:
        walk(a)
    return out


# --------------------------------------------------------------------------
# Transaction -> journal line explosion
# --------------------------------------------------------------------------

def _to_decimal(x: Any) -> Decimal:
    if x is None or x == "":
        return ZERO
    try:
        return Decimal(str(x))
    except (InvalidOperation, ValueError):
        return ZERO


CREDIT_NORMAL_TYPES = {"Liability", "Equity", "Income"}
# (Asset and Expense are debit-normal. Anything unknown defaults to debit-normal.)

# Buildium transaction types that move the affected account in the OPPOSITE
# of its natural direction. Everything else (Charge, Payment, Bill, Check,
# GeneralJournalEntry, Deposit, EFT, etc.) moves it in the natural direction.
# Verified empirically against /glaccounts/balances on 571 Hudson FY2025
# for account 40010 Maintenance Income (Income/credit-normal): Charges and
# Payments and GJEs all credited the account; a Credit memo debited it.
TXN_DECREASES_NATURAL = {
    "Credit",           # tenant credit memo — reduces a Charge
    "Refund",           # refund of a payment
    "Reversal",         # generic reversal
    "ChargeReversal",
    "PaymentReversal",
}


def _classify_amount(
    amount: Decimal, account_type: str, txn_type: str = "",
) -> tuple[Decimal, Decimal]:
    """
    Classify a Buildium journal-line Amount into (debit, credit).

    Buildium's Line schema has NO PostingType field — verified by direct
    inspection of /v1/generalledger/transactions response objects. Line
    keys are: GLAccount, Amount, IsCashPosting, ReferenceNumber, Memo,
    AccountingEntity. The Amount value is unsigned magnitude; direction
    must be inferred from the combination of account type and the parent
    transaction's TransactionType.

    Sign rule:
      * Account is credit-normal (Income / Liability / Equity):
          - Natural-direction txn (Charge, Payment, Bill, GJE, …) → credit
          - Decreasing txn (Credit memo, Refund, Reversal) → debit
      * Account is debit-normal (Asset / Expense):
          - Natural-direction txn → debit
          - Decreasing txn → credit

    Defensive: if a (rare) negative Amount is encountered, treat it as an
    explicit reversal of whatever direction the rule would otherwise pick.
    """
    decreases = txn_type in TXN_DECREASES_NATURAL
    if amount < 0:
        amount = -amount
        decreases = not decreases

    credit_normal = account_type in CREDIT_NORMAL_TYPES
    if credit_normal:
        return (amount, ZERO) if decreases else (ZERO, amount)
    else:
        return (ZERO, amount) if decreases else (amount, ZERO)


def _keep_line_for_basis(line: dict, txn_type: str, basis: str) -> bool:
    """
    Apply Buildium's basis convention client-side. The
    /v1/generalledger/transactions endpoint silently ignores the
    ?accountingbasis= query param (verified: identical result sets on
    Cash and Accrual), so the basis filter has to be enforced here.

    Verified empirically on 571 Hudson FY2025 / account 40010:
      Cash basis sum   = Payment lines + GJE lines       = $771,109.20
      Accrual sum      = Charge + GJE − Credit lines     = $759,541.56
      Both reconcile exactly to /v1/glaccounts/balances at the same date.

    Rule:
      - Cash:    keep lines where IsCashPosting == True (cash-realized
                 events) PLUS every GeneralJournalEntry line (manual JEs
                 are recognized in BOTH bases).
      - Accrual: keep lines where IsCashPosting == False (accrual-only
                 events: Charges, Bills, GJEs, Credits, Refunds).
    """
    if (txn_type or "") == "GeneralJournalEntry":
        return True
    is_cash = bool(line.get("IsCashPosting"))
    if basis == "Cash":
        return is_cash
    return not is_cash


def _find_undeposited_funds_id(accounts: dict[int, dict]) -> int | None:
    """Locate the Undeposited Funds GL account in the flattened chart."""
    for aid, a in accounts.items():
        if (a.get("Name") or "").strip().lower() == "undeposited funds":
            return aid
    return None


def explode_transactions(
    transactions: list[dict],
    association_id: int,
    accounts: dict[int, dict],
    operating_bank_id: int | None,
) -> tuple[list[dict], dict]:
    """
    Turn each Buildium transaction into a list of journal-line rows, keeping
    only lines whose AccountingEntity.Id matches association_id.

    IMPORTANT: Buildium's /v1/generalledger/transactions endpoint only
    surfaces the income/expense side of most transactions in Journal.Lines --
    the matching cash leg (bank debit for a Payment, bank credit for a Check,
    etc.) is implicit and never appears in the response. To produce a GL
    where total debits == total credits, we SYNTHESIZE the missing cash leg
    for every unbalanced transaction by adding a line against:

      - DepositDetails.BankGLAccountId, for Deposit transactions
      - operating_bank_id (from the association record), for everything else

    For Deposit transactions with empty Journal.Lines, we also synthesize the
    offsetting credit to Undeposited Funds.

    Returns (rows, stats) where stats is a dict with counts.
    """
    rows: list[dict] = []
    stats = {
        "with_lines": 0,
        "empty_journal": 0,
        "dropped_wrong_entity": 0,
        "synth_cash_legs": 0,
        "synth_deposit_pairs": 0,
        "unbalanced_after_synth": 0,
    }

    undeposited_id = _find_undeposited_funds_id(accounts)

    def acct_meta(gl_id: int) -> dict:
        a = accounts.get(gl_id, {})
        return {
            "gl_id": gl_id,
            "gl_name": a.get("Name") or f"(account {gl_id})",
            "gl_number": a.get("AccountNumber") or "",
            "gl_type": a.get("Type") or "Asset",
        }

    def emit(
        *, date_s, txn_id, txn_type, gl_id, memo, debit, credit, unit="", synthetic=False
    ):
        m = acct_meta(gl_id)
        rows.append(
            {
                "date": date_s,
                "txn_id": txn_id,
                "txn_type": txn_type,
                **m,
                "memo": memo,
                "debit": debit,
                "credit": credit,
                "unit": unit,
                "synthetic": synthetic,
            }
        )

    for txn in transactions:
        journal = txn.get("Journal") or {}
        src_lines = journal.get("Lines") or []
        txn_date = (txn.get("Date") or "")[:10]
        txn_type = txn.get("TransactionType") or ""
        txn_id = txn.get("Id")
        default_memo = journal.get("Memo") or ""
        unit_number = txn.get("UnitNumber") or ""
        total = _to_decimal(txn.get("TotalAmount"))
        dep = txn.get("DepositDetails") or {}
        dep_bank_id = dep.get("BankGLAccountId")

        txn_row_start = len(rows)

        # --- 1. Copy over real journal lines (filtered to this association) ---
        if src_lines:
            stats["with_lines"] += 1
            for line in src_lines:
                ae = (line.get("AccountingEntity") or {}).get("Id")
                if ae is not None and ae != association_id:
                    stats["dropped_wrong_entity"] += 1
                    continue
                # Basis filter: drop lines that don't apply to the current
                # accounting basis (the API ignores accountingbasis on this
                # endpoint, so we filter client-side via IsCashPosting).
                if not _keep_line_for_basis(line, txn_type, _BASIS):
                    stats.setdefault("dropped_wrong_basis", 0)
                    stats["dropped_wrong_basis"] += 1
                    continue
                gl = line.get("GLAccount") or {}
                gl_id = gl.get("Id")
                if gl_id is None:
                    continue
                amount = _to_decimal(line.get("Amount"))
                gl_type = gl.get("Type") or ""
                debit, credit = _classify_amount(amount, gl_type, txn_type)
                # Prefer the line's own account metadata if the id isn't in
                # our flattened chart (shouldn't happen but be defensive).
                if gl_id not in accounts:
                    accounts[gl_id] = {
                        "Id": gl_id,
                        "AccountNumber": gl.get("AccountNumber") or "",
                        "Name": gl.get("Name") or f"(account {gl_id})",
                        "Type": gl_type,
                    }
                emit(
                    date_s=txn_date,
                    txn_id=txn_id,
                    txn_type=txn_type,
                    gl_id=gl_id,
                    memo=line.get("Memo") or default_memo,
                    debit=debit,
                    credit=credit,
                    unit=unit_number,
                )
        else:
            stats["empty_journal"] += 1

        # --- 2. Compute imbalance and synthesize cash leg(s) ---
        this_txn_rows = rows[txn_row_start:]
        real_debit = sum((r["debit"] for r in this_txn_rows), ZERO)
        real_credit = sum((r["credit"] for r in this_txn_rows), ZERO)
        imbalance = real_debit - real_credit  # positive => need more credit

        if txn_type == "Deposit" and not src_lines and dep_bank_id is not None:
            # Special case: empty-journal deposit -> two synthetic legs
            if total > 0:
                emit(
                    date_s=txn_date,
                    txn_id=txn_id,
                    txn_type=txn_type,
                    gl_id=dep_bank_id,
                    memo=default_memo or "(deposit in)",
                    debit=total,
                    credit=ZERO,
                    synthetic=True,
                )
                if undeposited_id is not None:
                    emit(
                        date_s=txn_date,
                        txn_id=txn_id,
                        txn_type=txn_type,
                        gl_id=undeposited_id,
                        memo=default_memo or "(from undeposited funds)",
                        debit=ZERO,
                        credit=total,
                        synthetic=True,
                    )
                stats["synth_deposit_pairs"] += 1
            continue

        if imbalance == ZERO:
            continue  # already balanced (multi-leg JE, etc.)

        # Choose the cash account for this transaction's missing leg.
        cash_acct = dep_bank_id if dep_bank_id is not None else operating_bank_id
        if cash_acct is None:
            stats["unbalanced_after_synth"] += 1
            continue

        if imbalance > 0:
            # Too much debit -> need a credit to balance (cash out)
            emit(
                date_s=txn_date,
                txn_id=txn_id,
                txn_type=txn_type,
                gl_id=cash_acct,
                memo="(cash leg)",
                debit=ZERO,
                credit=imbalance,
                synthetic=True,
            )
        else:
            # Too much credit -> need a debit to balance (cash in)
            emit(
                date_s=txn_date,
                txn_id=txn_id,
                txn_type=txn_type,
                gl_id=cash_acct,
                memo="(cash leg)",
                debit=-imbalance,
                credit=ZERO,
                synthetic=True,
            )
        stats["synth_cash_legs"] += 1

    return rows, stats


def group_by_account(
    lines: list[dict],
) -> list[tuple[dict, list[dict], Decimal, Decimal]]:
    """
    Group lines by their GL account id, sort lines within each group by date,
    and sort groups by AccountNumber. Returns a list of
    (account_record, lines, total_debit, total_credit) tuples.

    Account metadata is pulled from the line records themselves (the embedded
    GLAccount block Buildium returns on each journal line), so we don't need
    a separate account map.
    """
    by_id: dict[int, list[dict]] = defaultdict(list)
    meta: dict[int, dict] = {}
    for line in lines:
        gid = line["gl_id"]
        by_id[gid].append(line)
        if gid not in meta:
            meta[gid] = {
                "Id": gid,
                "AccountNumber": line.get("gl_number") or "",
                "Name": line.get("gl_name") or f"(account {gid})",
                "Type": line.get("gl_type") or "",
            }

    groups: list[tuple[dict, list[dict], Decimal, Decimal]] = []
    for gl_id, ls in by_id.items():
        ls.sort(key=lambda x: (x["date"], x["txn_id"] or 0))
        td = sum((l["debit"] for l in ls), ZERO)
        tc = sum((l["credit"] for l in ls), ZERO)
        groups.append((meta[gl_id], ls, td, tc))

    groups.sort(
        key=lambda g: (g[0].get("AccountNumber") or "", g[0].get("Name") or "")
    )
    return groups


# --------------------------------------------------------------------------
# Report builders (income statement, balance sheet, trial balance)
# --------------------------------------------------------------------------

def build_income_statement(
    groups: list[tuple[dict, list[dict], Decimal, Decimal]],
    gl_activity_api: dict[int, Decimal] | None = None,
    accounts: dict[int, dict] | None = None,
) -> dict:
    """
    Return {
      'revenue':        [(account_meta, amount), ...],
      'total_revenue':  Decimal,
      'expenses':       [(account_meta, amount), ...],
      'total_expenses': Decimal,
      'net_income':     Decimal,
    }

    Source of truth: Buildium's /v1/glaccounts/balances endpoint, accessed
    via the gl_activity_api dict (closing − opening period activity). This
    is the only number that's reliably correct: it sees activity on shared
    P&L accounts (Maintenance Income, Property Taxes, etc.) that don't
    touch the building's own bank accounts, and it's the same number that
    Buildium itself shows in its UI.

    The fallback path (sum of transaction-derived debits/credits in
    `groups`) is only used when no API data was provided. It will be wrong
    for shared P&L accounts because the transaction-pull is filtered by
    the building's specific bank-account IDs and won't see Charge entries
    that only post to A/R + Income with no bank involvement.
    """
    revenue: list[tuple[dict, Decimal]] = []
    expenses: list[tuple[dict, Decimal]] = []

    if gl_activity_api and accounts:
        # PRIMARY PATH — source of truth is the balance endpoint.
        # For each account that had non-zero period activity on this
        # association, look up its metadata and bucket by Type.
        seen_in_groups = {acct.get("Id"): acct for acct, _, _, _ in groups if acct.get("Id")}
        for aid, activity in gl_activity_api.items():
            if activity == ZERO:
                continue
            acct = seen_in_groups.get(aid) or accounts.get(aid)
            if not acct:
                continue
            t = acct.get("Type")
            # Make a slim acct dict for the report regardless of source.
            acct_meta = {
                "Id": aid,
                "AccountNumber": acct.get("AccountNumber") or "",
                "Name": acct.get("Name") or f"(account {aid})",
                "Type": t,
            }
            if t == "Income":
                revenue.append((acct_meta, activity))
            elif t == "Expense":
                expenses.append((acct_meta, activity))
    else:
        # FALLBACK — derive from transaction sums (legacy behavior).
        for acct, _lines, td, tc in groups:
            t = acct.get("Type")
            if t == "Income":
                revenue.append((acct, tc - td))
            elif t == "Expense":
                expenses.append((acct, td - tc))

    revenue.sort(key=lambda x: (x[0].get("AccountNumber") or "", x[0].get("Name") or ""))
    expenses.sort(key=lambda x: (x[0].get("AccountNumber") or "", x[0].get("Name") or ""))
    total_revenue = sum((x[1] for x in revenue), ZERO)
    total_expenses = sum((x[1] for x in expenses), ZERO)
    return {
        "revenue": revenue,
        "total_revenue": total_revenue,
        "expenses": expenses,
        "total_expenses": total_expenses,
        "net_income": total_revenue - total_expenses,
    }


def build_balance_sheet(
    groups: list[tuple[dict, list[dict], Decimal, Decimal]],
    accounts: dict[int, dict],
    gl_balances_close: dict[int, Decimal] | None = None,
    gl_activity_api: dict[int, Decimal] | None = None,
) -> dict:
    """
    Return a balance sheet structured by Type then SubType.

    Source of truth: Buildium's /v1/glaccounts/balances endpoint at the
    period-end as-of date (gl_balances_close). The endpoint returns each
    account in normal-balance direction (positive = natural-side balance),
    so we can use the values directly without sign flips. Income and
    Expense period activity is taken from gl_activity_api (closing −
    opening) and rolled into a synthetic Current Period Earnings line in
    Equity so the accounting equation holds within-period.

    Fallback path: if no API data is provided, derive balances from the
    transaction-derived `groups` (legacy behavior, will be wrong for
    accounts not touched by the building's own bank accounts).
    """
    sections: dict[str, dict[str, list[tuple[dict, Decimal]]]] = {
        "assets": defaultdict(list),
        "liabilities": defaultdict(list),
        "equity": defaultdict(list),
    }
    total_income = ZERO  # credit-normal: credits - debits
    total_expense = ZERO  # debit-normal: debits - credits

    if gl_balances_close is not None and gl_activity_api is not None:
        # PRIMARY PATH — source of truth is the balance endpoint.
        seen_in_groups = {a.get("Id"): a for a, _, _, _ in groups if a.get("Id")}
        for aid, bal in gl_balances_close.items():
            if bal == ZERO:
                continue
            acct = seen_in_groups.get(aid) or accounts.get(aid)
            if not acct:
                continue
            t = acct.get("Type")
            sub = acct.get("SubType") or (accounts.get(aid) or {}).get("SubType") or "Other"
            acct_meta = {
                "Id": aid,
                "AccountNumber": acct.get("AccountNumber") or "",
                "Name": acct.get("Name") or f"(account {aid})",
                "Type": t,
                "SubType": sub,
            }
            if t == "Asset":
                sections["assets"][sub].append((acct_meta, bal))
            elif t == "Liability":
                sections["liabilities"][sub].append((acct_meta, bal))
            elif t == "Equity":
                sections["equity"][sub].append((acct_meta, bal))
        # Income/Expense for the period rolls into Current Period Earnings.
        for aid, activity in gl_activity_api.items():
            t = (accounts.get(aid) or {}).get("Type")
            if t == "Income":
                total_income += activity
            elif t == "Expense":
                total_expense += activity
    else:
        # FALLBACK — derive from transaction sums (legacy behavior).
        for acct, _lines, td, tc in groups:
            t = acct.get("Type")
            sub = acct.get("SubType")
            if not sub:
                full = accounts.get(acct.get("Id") or -1) or {}
                sub = full.get("SubType") or "Other"
            if t == "Asset":
                sections["assets"][sub].append((acct, td - tc))
            elif t == "Liability":
                sections["liabilities"][sub].append((acct, tc - td))
            elif t == "Equity":
                sections["equity"][sub].append((acct, tc - td))
            elif t == "Income":
                total_income += tc - td
            elif t == "Expense":
                total_expense += td - tc

    current_period_earnings = total_income - total_expense
    # Add a synthetic Equity line so A = L + E holds within-period.
    sections["equity"]["Current Period Earnings"].append(
        (
            {
                "Id": None,
                "AccountNumber": "",
                "Name": "Current Period Earnings (Income - Expenses)",
                "Type": "Equity",
                "SubType": "Current Period Earnings",
            },
            current_period_earnings,
        )
    )

    def sort_section(s: dict) -> dict:
        return {
            sub: sorted(
                rows,
                key=lambda x: (x[0].get("AccountNumber") or "", x[0].get("Name") or ""),
            )
            for sub, rows in sorted(s.items())
        }

    def sum_section(s: dict) -> Decimal:
        return sum((r[1] for grp in s.values() for r in grp), ZERO)

    assets = sort_section(sections["assets"])
    liabilities = sort_section(sections["liabilities"])
    equity = sort_section(sections["equity"])
    total_assets = sum_section(assets)
    total_liabilities = sum_section(liabilities)
    total_equity = sum_section(equity)
    liab_plus_equity = total_liabilities + total_equity

    return {
        "assets": assets,
        "total_assets": total_assets,
        "liabilities": liabilities,
        "total_liabilities": total_liabilities,
        "equity": equity,
        "total_equity": total_equity,
        "liab_plus_equity": liab_plus_equity,
        "current_period_earnings": current_period_earnings,
        "balances": abs(total_assets - liab_plus_equity) < Decimal("0.01"),
    }


def build_trial_balance(
    groups: list[tuple[dict, list[dict], Decimal, Decimal]],
    gl_activity_api: dict[int, Decimal] | None = None,
    accounts: dict[int, dict] | None = None,
) -> dict:
    """
    Flat list of (account, debit_balance, credit_balance) with totals.

    Source of truth: Buildium's /v1/glaccounts/balances endpoint period
    activity (gl_activity_api). Values come back in normal-balance form
    (positive = natural-side movement); we convert to debit-positive form
    for trial-balance presentation:
      Asset, Expense  → debit column (positive activity = debit)
      Liability, Equity, Income → credit column (positive activity = credit)

    Fallback path: if no API data is provided, derive from transaction
    sums in `groups` (legacy behavior).
    """
    rows: list[tuple[dict, Decimal, Decimal]] = []

    if gl_activity_api and accounts:
        # PRIMARY PATH — source of truth is the balance endpoint.
        seen_in_groups = {a.get("Id"): a for a, _, _, _ in groups if a.get("Id")}
        for aid, activity in gl_activity_api.items():
            if activity == ZERO:
                continue
            acct = seen_in_groups.get(aid) or accounts.get(aid)
            if not acct:
                continue
            t = acct.get("Type")
            acct_meta = {
                "Id": aid,
                "AccountNumber": acct.get("AccountNumber") or "",
                "Name": acct.get("Name") or f"(account {aid})",
                "Type": t,
            }
            # Convert normal-balance form to debit-positive
            if t in ("Liability", "Equity", "Income"):
                # credit-normal: positive activity = credit-side
                rows.append((acct_meta, ZERO, activity))
            else:
                # debit-normal (Asset, Expense, default): positive = debit
                rows.append((acct_meta, activity, ZERO))
    else:
        # FALLBACK — derive from transaction sums.
        for acct, _lines, td, tc in groups:
            net = td - tc
            if net >= ZERO:
                rows.append((acct, net, ZERO))
            else:
                rows.append((acct, ZERO, -net))

    rows.sort(key=lambda x: (x[0].get("AccountNumber") or "", x[0].get("Name") or ""))
    total_debit = sum((r[1] for r in rows), ZERO)
    total_credit = sum((r[2] for r in rows), ZERO)
    return {
        "rows": rows,
        "total_debit": total_debit,
        "total_credit": total_credit,
    }


# --------------------------------------------------------------------------
# Extended report builders
#
# Each builder takes pre-fetched data and returns a report spec dict shaped
# for the generic write_excel_table / write_pdf_table helpers:
#
#     {
#       "columns":    list of column dicts,
#       "rows":       list of row dicts,
#       "totals_row": optional dict of totals (column key -> value),
#       "summary":    list of (label, value, kind) for Summary tab,
#       "notes":      list of note strings shown under the title,
#       "sheet_name": Excel tab name,
#       "landscape":  bool,
#     }
# --------------------------------------------------------------------------

def _aging_bucket(days_past_due: int) -> str:
    if days_past_due < 0:
        return "current"
    if days_past_due <= 30:
        return "d0_30"
    if days_past_due <= 60:
        return "d31_60"
    if days_past_due <= 90:
        return "d61_90"
    return "d90_plus"


def build_ap_aging(
    headers: dict, bills: list[dict], as_of: date, vendor_cache: dict[int, dict],
) -> dict:
    """
    Group unpaid bills by vendor, bucket by aging (based on DueDate vs as_of).
    Columns: Vendor | Invoice # | Invoice Date | Due Date | Amount | Current |
             1-30 | 31-60 | 61-90 | 90+ | Total
    """
    rows: list[dict] = []
    totals = {
        "amount": ZERO, "current": ZERO, "d0_30": ZERO,
        "d31_60": ZERO, "d61_90": ZERO, "d90_plus": ZERO, "total": ZERO,
    }
    # Sort by vendor for readability (resolve names first)
    enriched: list[tuple[str, dict]] = []
    for b in bills:
        vid = b.get("VendorId")
        vendor_name = "(unknown)"
        if vid:
            vendor_name = vendor_display_name(fetch_vendor(headers, vid, vendor_cache))
        enriched.append((vendor_name, b))
    enriched.sort(key=lambda x: (x[0].lower(), x[1].get("DueDate") or ""))

    for vendor_name, b in enriched:
        amount = sum(
            (_to_decimal(line.get("Amount")) for line in (b.get("Lines") or [])),
            ZERO,
        )
        due_date_s = (b.get("DueDate") or "")[:10]
        bucket_key = "current"
        days = 0
        if due_date_s:
            try:
                due = datetime.strptime(due_date_s, "%Y-%m-%d").date()
                days = (as_of - due).days
                bucket_key = _aging_bucket(days)
            except ValueError:
                pass
        row = {
            "vendor": vendor_name,
            "invoice": b.get("ReferenceNumber") or "",
            "inv_date": (b.get("Date") or "")[:10],
            "due_date": due_date_s,
            "amount": amount,
            "current": ZERO, "d0_30": ZERO, "d31_60": ZERO, "d61_90": ZERO, "d90_plus": ZERO,
            "total": amount,
        }
        row[bucket_key] = amount
        rows.append(row)
        totals["amount"] += amount
        totals[bucket_key] += amount
        totals["total"] += amount

    columns = [
        {"header": "Vendor",      "key": "vendor",    "width": 32, "pdf_width": 2.0},
        {"header": "Invoice #",   "key": "invoice",   "width": 16, "pdf_width": 1.0},
        {"header": "Invoice Date","key": "inv_date",  "kind": "date", "width": 12, "pdf_width": 0.85},
        {"header": "Due Date",    "key": "due_date",  "kind": "date", "width": 12, "pdf_width": 0.85},
        {"header": "Amount",      "key": "amount",    "kind": "money", "width": 13, "pdf_width": 1.0},
        {"header": "Current",     "key": "current",   "kind": "money", "width": 12, "pdf_width": 0.9},
        {"header": "1-30",        "key": "d0_30",     "kind": "money", "width": 12, "pdf_width": 0.9},
        {"header": "31-60",       "key": "d31_60",    "kind": "money", "width": 12, "pdf_width": 0.9},
        {"header": "61-90",       "key": "d61_90",    "kind": "money", "width": 12, "pdf_width": 0.9},
        {"header": "90+",         "key": "d90_plus",  "kind": "money", "width": 12, "pdf_width": 0.9},
        {"header": "Total",       "key": "total",     "kind": "money", "width": 13, "pdf_width": 1.0},
    ]
    return {
        "columns": columns,
        "rows": rows,
        "totals_row": totals,
        "summary": [
            ("Unpaid bills",   len(rows), "int"),
            ("Total open AP",  totals["total"], "money"),
            ("Current",        totals["current"], "money"),
            ("1-30 days",      totals["d0_30"], "money"),
            ("31-60 days",     totals["d31_60"], "money"),
            ("61-90 days",     totals["d61_90"], "money"),
            ("90+ days",       totals["d90_plus"], "money"),
        ],
        "notes": [f"Aging as of {as_of.isoformat()}"],
        "sheet_name": "AP Aging",
        "landscape": True,
    }


def build_ar_aging(
    outstanding: list[dict],
    units: list[dict],
    owners: list[dict],
) -> dict:
    """
    Buildium returns pre-computed 4 buckets (0-30, 31-60, 61-90, 90+) — no
    separate 'Current' column. We follow Buildium's buckets as-is.

    Join outstanding balances to units + owners for display names.
    """
    units_by_id = {u["Id"]: u for u in units}
    owner_by_oa_id: dict[int, dict] = {}
    for o in owners:
        for oa in o.get("OwnershipAccounts") or []:
            owner_by_oa_id[oa["Id"]] = o

    rows: list[dict] = []
    totals = {"d0_30": ZERO, "d31_60": ZERO, "d61_90": ZERO, "d90_plus": ZERO, "total": ZERO}
    for b in outstanding:
        oa_id = b.get("OwnershipAccountId")
        unit = units_by_id.get(b.get("UnitId") or -1, {})
        owner = owner_by_oa_id.get(oa_id or -1, {})
        owner_name = f"{owner.get('FirstName','')} {owner.get('LastName','')}".strip() or "(unknown)"
        row = {
            "unit":     unit.get("UnitNumber") or "",
            "owner":    owner_name,
            "d0_30":    _to_decimal(b.get("Balance0To30Days")),
            "d31_60":   _to_decimal(b.get("Balance31To60Days")),
            "d61_90":   _to_decimal(b.get("Balance61To90Days")),
            "d90_plus": _to_decimal(b.get("BalanceOver90Days")),
            "total":    _to_decimal(b.get("TotalBalance")),
        }
        rows.append(row)
        for k in ("d0_30", "d31_60", "d61_90", "d90_plus", "total"):
            totals[k] += row[k]

    rows.sort(key=lambda r: (r["unit"], r["owner"]))

    columns = [
        {"header": "Unit",   "key": "unit",     "width": 10, "pdf_width": 0.8},
        {"header": "Owner",  "key": "owner",    "width": 30, "pdf_width": 2.3},
        {"header": "0-30",   "key": "d0_30",    "kind": "money", "width": 14, "pdf_width": 1.1},
        {"header": "31-60",  "key": "d31_60",   "kind": "money", "width": 14, "pdf_width": 1.1},
        {"header": "61-90",  "key": "d61_90",   "kind": "money", "width": 14, "pdf_width": 1.1},
        {"header": "90+",    "key": "d90_plus", "kind": "money", "width": 14, "pdf_width": 1.1},
        {"header": "Total",  "key": "total",    "kind": "money", "width": 14, "pdf_width": 1.1},
    ]
    return {
        "columns": columns,
        "rows": rows,
        "totals_row": totals,
        "summary": [
            ("Units with balance", len([r for r in rows if r["total"] != ZERO]), "int"),
            ("Total AR",           totals["total"], "money"),
            ("0-30 days",          totals["d0_30"], "money"),
            ("31-60 days",         totals["d31_60"], "money"),
            ("61-90 days",         totals["d61_90"], "money"),
            ("90+ days",           totals["d90_plus"], "money"),
        ],
        "notes": ["Buildium provides 4 aging buckets (no separate 'Current' vs 0-30 split)"],
        "sheet_name": "AR Aging",
        "landscape": False,
    }


def build_budget_vs_actual(
    budget: dict | None,
    groups: list,
    accounts: dict[int, dict],
    gl_activity_api: dict[int, Decimal] | None = None,
) -> dict:
    """
    Join budget.Details[] by GLAccountId with actuals from the GL period
    activity. Only Income and Expense accounts are included — budgets
    cover P&L, not balance sheet.

    Source of truth for actuals: Buildium's /v1/glaccounts/balances period
    activity (gl_activity_api). Activity is already in normal-balance form
    (positive = natural-side movement), so for both Income and Expense the
    value matches what the board would call "actual spend / actual income".

    Fallback: derive from `groups` (transaction sums) when no API data is
    provided.
    """
    actuals_by_gl: dict[int, Decimal] = {}
    if gl_activity_api and accounts:
        for aid, activity in gl_activity_api.items():
            t = (accounts.get(aid) or {}).get("Type")
            if t in ("Income", "Expense") and activity != ZERO:
                actuals_by_gl[aid] = activity
    else:
        for acct, _lines, td, tc in groups:
            t = acct.get("Type")
            if t not in ("Income", "Expense"):
                continue
            if t == "Income":
                amt = tc - td  # credit-normal
            else:
                amt = td - tc  # debit-normal
            actuals_by_gl[acct.get("Id") or -1] = amt

    budget_by_gl: dict[int, Decimal] = {}
    if budget:
        for d in budget.get("Details") or []:
            gl_id = d.get("GLAccountId")
            # Only include P&L accounts on the budget side too.
            sub = (d.get("GLAccountSubType") or "").lower()
            looks_pl = "income" in sub or "expense" in sub
            acct_type = (accounts.get(gl_id) or {}).get("Type")
            if acct_type in ("Income", "Expense") or looks_pl:
                budget_by_gl[gl_id] = _to_decimal(d.get("TotalAmount"))

    all_gl_ids = set(actuals_by_gl.keys()) | set(budget_by_gl.keys())
    rows: list[dict] = []
    for gl_id in all_gl_ids:
        # Pull metadata from the chart of accounts first (comprehensive),
        # fall back to an "(account N)" placeholder only if truly unknown.
        meta = accounts.get(gl_id) or {}
        acct_num = meta.get("AccountNumber") or ""
        acct_name = meta.get("Name") or f"(account {gl_id})"
        acct_type = meta.get("Type") or ""
        budget_amt = budget_by_gl.get(gl_id, ZERO)
        actual = actuals_by_gl.get(gl_id, ZERO)
        variance = actual - budget_amt
        variance_pct = None
        if budget_amt != ZERO:
            variance_pct = float(variance / budget_amt)
        rows.append({
            "acct_num":  acct_num,
            "acct_name": acct_name,
            "acct_type": acct_type,
            "budget":    budget_amt,
            "actual":    actual,
            "variance":  variance,
            "variance_pct": variance_pct,
        })

    rows = [r for r in rows if r["budget"] != ZERO or r["actual"] != ZERO]
    rows.sort(key=lambda r: (r["acct_type"], r["acct_num"], r["acct_name"]))

    totals = {
        "budget":   sum((r["budget"] for r in rows), ZERO),
        "actual":   sum((r["actual"] for r in rows), ZERO),
        "variance": sum((r["variance"] for r in rows), ZERO),
    }

    columns = [
        {"header": "Account #",   "key": "acct_num",  "width": 12, "pdf_width": 0.9},
        {"header": "Account Name","key": "acct_name", "width": 40, "pdf_width": 3.2},
        {"header": "Type",        "key": "acct_type", "width": 11, "pdf_width": 0.9},
        {"header": "Budget",      "key": "budget",    "kind": "money", "width": 14, "pdf_width": 1.1},
        {"header": "Actual",      "key": "actual",    "kind": "money", "width": 14, "pdf_width": 1.1},
        {"header": "Variance $",  "key": "variance",  "kind": "money", "width": 14, "pdf_width": 1.1},
        {"header": "Var %",       "key": "variance_pct", "kind": "pct",   "width": 10, "pdf_width": 0.8},
    ]
    return {
        "columns": columns,
        "rows": rows,
        "totals_row": totals,
        "summary": [
            ("Budget name",    budget.get("Name") if budget else "(no budget)", "text"),
            ("Accounts with activity or budget", len(rows), "int"),
            ("Total Budget",   totals["budget"], "money"),
            ("Total Actual",   totals["actual"], "money"),
            ("Total Variance", totals["variance"], "money"),
        ],
        "notes": None if budget else ["No budget found for this fiscal year"],
        "sheet_name": "Budget vs Actual",
        "landscape": True,
    }


def build_check_register(
    headers: dict, checks: list[dict], vendor_cache: dict[int, dict],
) -> dict:
    rows: list[dict] = []
    total = ZERO
    for c in sorted(checks, key=lambda x: (x.get("EntryDate") or "", x.get("CheckNumber") or "")):
        payee = c.get("Payee") or {}
        payee_type = payee.get("Type") or ""
        payee_id = payee.get("Id")
        # Buildium's Check.Payee is {Id, Type, Href} with NO name. For
        # Vendor payees we dereference via the vendor cache; for other
        # types (AssociationOwner, Employee) we fall back to type+id.
        if payee_type == "Vendor" and payee_id:
            payee_name = vendor_display_name(fetch_vendor(headers, payee_id, vendor_cache))
        else:
            payee_name = payee.get("Name") or f"{payee_type} {payee_id}".strip()
        lines = c.get("Lines") or []
        gl_labels = []
        for line in lines:
            gl_labels.append(str(line.get("GLAccountId") or ""))
        gl_label = ", ".join(g for g in gl_labels if g) or ""
        amount = _to_decimal(c.get("TotalAmount"))
        rows.append({
            "check_num": c.get("CheckNumber") or "",
            "date":      (c.get("EntryDate") or "")[:10],
            "payee":     payee_name,
            "amount":    amount,
            "memo":      (c.get("Memo") or "")[:120],
            "gl":        gl_label,
        })
        total += amount

    columns = [
        {"header": "Check #",    "key": "check_num", "width": 12, "pdf_width": 0.8},
        {"header": "Date",       "key": "date",      "kind": "date", "width": 12, "pdf_width": 0.9},
        {"header": "Payee",      "key": "payee",     "width": 28, "pdf_width": 2.2},
        {"header": "Amount",     "key": "amount",    "kind": "money", "width": 13, "pdf_width": 1.1},
        {"header": "Memo",       "key": "memo",      "width": 40, "pdf_width": 3.0},
        {"header": "GL Account", "key": "gl",        "width": 14, "pdf_width": 1.1},
    ]
    return {
        "columns": columns,
        "rows": rows,
        "totals_row": {"amount": total},
        "summary": [("Checks issued", len(rows), "int"), ("Total amount", total, "money")],
        "notes": None,
        "sheet_name": "Check Register",
        "landscape": True,
    }


def build_rent_roll(
    units: list[dict], owners: list[dict], outstanding: list[dict],
    budget: dict | None,
) -> dict:
    # Maintenance Income GL id 78820 (observed) -- use budget monthly amount
    # as the "monthly assessment" fallback if present.
    monthly_assessment_total = ZERO
    if budget:
        for d in budget.get("Details") or []:
            sub = d.get("GLAccountSubType") or ""
            if sub == "Income":
                monthly_amts = d.get("MonthlyAmounts") or {}
                vals = [_to_decimal(v) for v in monthly_amts.values()]
                if vals:
                    monthly_assessment_total += max(vals)  # typical monthly assessment

    n_units = len(units) or 1
    avg_monthly = (monthly_assessment_total / n_units) if monthly_assessment_total else ZERO

    owner_by_oa_id: dict[int, dict] = {}
    move_in_by_oa_id: dict[int, str] = {}
    for o in owners:
        for oa in o.get("OwnershipAccounts") or []:
            owner_by_oa_id.setdefault(oa["Id"], o)
            move_in_by_oa_id.setdefault(oa["Id"], (oa.get("DateOfPurchase") or "")[:10])

    # map unit id -> balance
    balance_by_unit: dict[int, Decimal] = {}
    for b in outstanding:
        uid = b.get("UnitId")
        if uid is not None:
            balance_by_unit[uid] = balance_by_unit.get(uid, ZERO) + _to_decimal(b.get("TotalBalance"))

    # map unit id -> (owner, move_in) via owner's OwnershipAccounts
    owner_by_unit: dict[int, tuple[dict, str]] = {}
    for o in owners:
        for oa in o.get("OwnershipAccounts") or []:
            uid = oa.get("UnitId")
            if uid is not None and uid not in owner_by_unit:
                owner_by_unit[uid] = (o, (oa.get("DateOfPurchase") or "")[:10])

    rows: list[dict] = []
    total_balance = ZERO
    for u in sorted(units, key=lambda x: x.get("UnitNumber") or ""):
        uid = u.get("Id")
        owner, move_in = owner_by_unit.get(uid or -1, ({}, ""))
        owner_name = f"{owner.get('FirstName','')} {owner.get('LastName','')}".strip() or "(vacant)"
        balance = balance_by_unit.get(uid or -1, ZERO)
        rows.append({
            "unit":    u.get("UnitNumber") or "",
            "owner":   owner_name,
            "move_in": move_in,
            "monthly": avg_monthly if monthly_assessment_total else ZERO,
            "balance": balance,
        })
        total_balance += balance

    columns = [
        {"header": "Unit",               "key": "unit",    "width": 10, "pdf_width": 0.8},
        {"header": "Owner Name",         "key": "owner",   "width": 32, "pdf_width": 2.5},
        {"header": "Move-in Date",       "key": "move_in", "kind": "date", "width": 14, "pdf_width": 1.1},
        {"header": "Monthly Assessment", "key": "monthly", "kind": "money", "width": 18, "pdf_width": 1.4},
        {"header": "Balance",            "key": "balance", "kind": "money", "width": 14, "pdf_width": 1.1},
    ]
    note = None
    if not monthly_assessment_total:
        note = "Monthly assessment not available (no budget Income entries); shown as $0"
    else:
        note = "Monthly assessment shown as (budget monthly Income) / (# of units) — approximation"
    return {
        "columns": columns,
        "rows": rows,
        "totals_row": {"balance": total_balance},
        "summary": [
            ("Units",         len(rows), "int"),
            ("Total balance", total_balance, "money"),
        ],
        "notes": [note],
        "sheet_name": "Rent Roll",
        "landscape": False,
    }


def build_owner_statement(
    txns: list[dict], ownership_account_id: int,
    owners: list[dict], units: list[dict],
    start_date: str, end_date: str,
) -> dict:
    """
    Running-balance owner statement. Header includes owner name + unit.

    NOTE: Buildium's /v1/associations/ownershipaccounts/{id}/transactions
    endpoint silently ignores the startdate/enddate filters, so we apply
    a client-side date filter before computing the running balance.
    """
    # Client-side date filter (the endpoint ignores its own date params).
    txns = [
        t for t in txns
        if start_date <= (t.get("Date") or "")[:10] <= end_date
    ]
    # Look up owner + unit for the header
    owner_name = ""
    unit_number = ""
    for o in owners:
        for oa in o.get("OwnershipAccounts") or []:
            if oa.get("Id") == ownership_account_id:
                owner_name = f"{o.get('FirstName','')} {o.get('LastName','')}".strip()
                unit_id = oa.get("UnitId")
                for u in units:
                    if u.get("Id") == unit_id:
                        unit_number = u.get("UnitNumber") or ""
                        break
                break
        if owner_name:
            break

    rows: list[dict] = []
    # Sort transactions by date ascending
    txns_sorted = sorted(txns, key=lambda t: (t.get("Date") or "", t.get("Id") or 0))
    running = ZERO
    for t in txns_sorted:
        total = _to_decimal(t.get("TotalAmount"))
        # Convention: positive TotalAmount = charge, negative = payment.
        # From probe we saw a Payment with TotalAmount=-3900.63 — so negative = payment.
        if total >= ZERO:
            charge, payment = total, ZERO
        else:
            charge, payment = ZERO, -total
        running += charge - payment
        memo = ((t.get("Journal") or {}).get("Memo")) or t.get("TransactionType") or ""
        rows.append({
            "date":       (t.get("Date") or "")[:10],
            "desc":       f"{t.get('TransactionType','')}: {memo}",
            "charge":     charge,
            "payment":    payment,
            "balance":    running,
        })

    columns = [
        {"header": "Date",        "key": "date",    "kind": "date", "width": 12, "pdf_width": 0.9},
        {"header": "Description", "key": "desc",    "width": 50, "pdf_width": 3.6},
        {"header": "Charge",      "key": "charge",  "kind": "money", "width": 14, "pdf_width": 1.1},
        {"header": "Payment",     "key": "payment", "kind": "money", "width": 14, "pdf_width": 1.1},
        {"header": "Balance",     "key": "balance", "kind": "money", "width": 14, "pdf_width": 1.1},
    ]
    total_charges = sum((r["charge"] for r in rows), ZERO)
    total_payments = sum((r["payment"] for r in rows), ZERO)
    ending_balance = total_charges - total_payments

    owner_line = f"Owner: {owner_name or '(unknown)'}  |  Unit: {unit_number or '(unknown)'}"
    return {
        "columns": columns,
        "rows": rows,
        "totals_row": {"charge": total_charges, "payment": total_payments, "balance": ending_balance},
        "summary": [
            ("Owner",           owner_name, "text"),
            ("Unit",            unit_number, "text"),
            ("Transactions",    len(rows), "int"),
            ("Total charges",   total_charges, "money"),
            ("Total payments",  total_payments, "money"),
            ("Ending balance",  ending_balance, "money"),
        ],
        "notes": [owner_line],
        "sheet_name": "Owner Statement",
        "landscape": False,
    }


def build_vendor_payment_summary(
    headers: dict, bills: list[dict], vendor_cache: dict[int, dict],
) -> dict:
    """Group paid bills by vendor, sum payments, track last payment date."""
    by_vendor: dict[int, dict] = {}
    for b in bills:
        vid = b.get("VendorId") or 0
        amount = sum(
            (_to_decimal(line.get("Amount")) for line in (b.get("Lines") or [])),
            ZERO,
        )
        paid_date = (b.get("PaidDate") or "")[:10]
        if vid not in by_vendor:
            by_vendor[vid] = {"count": 0, "total": ZERO, "last_paid": "", "vendor_id": vid}
        entry = by_vendor[vid]
        entry["count"] += 1
        entry["total"] += amount
        if paid_date > entry["last_paid"]:
            entry["last_paid"] = paid_date

    rows: list[dict] = []
    grand_total = ZERO
    for vid, entry in by_vendor.items():
        vname = vendor_display_name(fetch_vendor(headers, vid, vendor_cache)) if vid else "(unknown)"
        rows.append({
            "vendor":    vname,
            "count":     entry["count"],
            "total":     entry["total"],
            "last_paid": entry["last_paid"],
        })
        grand_total += entry["total"]
    rows.sort(key=lambda r: -float(r["total"]))

    columns = [
        {"header": "Vendor",            "key": "vendor",    "width": 36, "pdf_width": 3.0},
        {"header": "# of Payments",     "key": "count",     "kind": "int",   "width": 14, "pdf_width": 1.0},
        {"header": "Total Paid",        "key": "total",     "kind": "money", "width": 16, "pdf_width": 1.2},
        {"header": "Last Payment Date", "key": "last_paid", "kind": "date",  "width": 18, "pdf_width": 1.3},
    ]
    return {
        "columns": columns,
        "rows": rows,
        "totals_row": {"total": grand_total},
        "summary": [
            ("Vendors paid",       len(rows), "int"),
            ("Total paid",         grand_total, "money"),
            ("Bills paid",         sum(r["count"] for r in rows), "int"),
        ],
        "notes": ["For 1099 prep — verify 1099-eligible vendors receiving $600+ separately"],
        "sheet_name": "Vendor Payments",
        "landscape": False,
    }


def build_bank_register(txns: list[dict]) -> dict:
    rows: list[dict] = []
    for t in sorted(txns, key=lambda x: (x.get("EntryDate") or "", x.get("Id") or 0)):
        paid_by = t.get("PaidBy") or []
        paid_to = t.get("PaidTo") or []
        desc_parts = []
        for p in paid_to:
            desc_parts.append(p.get("Name") or p.get("Type") or "")
        for p in paid_by:
            ae = p.get("AccountingEntity") or {}
            desc_parts.append(ae.get("AccountingEntityType") or "")
        desc = (t.get("Memo") or "") or " / ".join(x for x in desc_parts if x)
        rows.append({
            "date":    (t.get("EntryDate") or "")[:10],
            "type":    t.get("TransactionType") or "",
            "desc":    (desc or "")[:80],
            "amount":  _to_decimal(t.get("Amount")),
            "balance": _to_decimal(t.get("Balance")),
        })
    columns = [
        {"header": "Date",            "key": "date",    "kind": "date",  "width": 12, "pdf_width": 0.9},
        {"header": "Type",            "key": "type",    "width": 14, "pdf_width": 1.1},
        {"header": "Description",     "key": "desc",    "width": 50, "pdf_width": 4.0},
        {"header": "Amount",          "key": "amount",  "kind": "money", "width": 14, "pdf_width": 1.2},
        {"header": "Running Balance", "key": "balance", "kind": "money", "width": 16, "pdf_width": 1.3},
    ]
    return {
        "columns": columns,
        "rows": rows,
        "totals_row": None,  # Running balance already carries the total
        "summary": [
            ("Transactions", len(rows), "int"),
            ("Ending balance", rows[-1]["balance"] if rows else ZERO, "money"),
        ],
        "notes": None,
        "sheet_name": "Bank Register",
        "landscape": True,
    }


def build_deposit_detail(deposits: list[dict]) -> dict:
    rows: list[dict] = []
    total = ZERO
    for d in sorted(deposits, key=lambda x: (x.get("EntryDate") or "", x.get("Id") or 0)):
        amt = _to_decimal(d.get("TotalAmount"))
        pt_ids = d.get("PaymentTransactionIds") or []
        lines = d.get("Lines") or []
        if lines:
            breakdown_parts = []
            for line in lines:
                name = (line.get("PaidBy") or {}).get("Name") or ""
                amt_l = _to_decimal(line.get("Amount"))
                breakdown_parts.append(f"{name}: {_fmt_money_always(amt_l)}")
            breakdown = "; ".join(breakdown_parts)[:150]
        elif pt_ids:
            breakdown = f"{len(pt_ids)} payment txn(s): {', '.join(str(i) for i in pt_ids[:6])}"
        else:
            breakdown = d.get("Memo") or ""
        rows.append({
            "date":       (d.get("EntryDate") or "")[:10],
            "amount":     amt,
            "n_items":    max(len(lines), len(pt_ids), 1),
            "breakdown":  breakdown,
        })
        total += amt

    columns = [
        {"header": "Deposit Date", "key": "date",      "kind": "date",  "width": 14, "pdf_width": 1.0},
        {"header": "Total Amount", "key": "amount",    "kind": "money", "width": 14, "pdf_width": 1.2},
        {"header": "# Items",      "key": "n_items",   "kind": "int",   "width": 10, "pdf_width": 0.8},
        {"header": "Breakdown",    "key": "breakdown", "width": 60, "pdf_width": 5.5},
    ]
    return {
        "columns": columns,
        "rows": rows,
        "totals_row": {"amount": total},
        "summary": [
            ("Deposits",    len(rows), "int"),
            ("Total deposited", total, "money"),
        ],
        "notes": None,
        "sheet_name": "Deposit Detail",
        "landscape": True,
    }


def build_board_roster(members: list[dict]) -> dict:
    rows: list[dict] = []
    for m in members:
        first = m.get("FirstName") or ""
        last = m.get("LastName") or ""
        name = f"{first} {last}".strip() or m.get("Name") or "(unknown)"
        # Board member term is often nested — defensive access
        term_start = (
            m.get("TermStartDate")
            or (m.get("BoardMemberTerm") or {}).get("StartDate")
            or ""
        )
        term_end = (
            m.get("TermEndDate")
            or (m.get("BoardMemberTerm") or {}).get("EndDate")
            or ""
        )
        phones = m.get("PhoneNumbers") or []
        phone = phones[0].get("Number") if phones else ""
        rows.append({
            "name":       name,
            "position":   m.get("Position") or (m.get("BoardMemberTerm") or {}).get("Position") or "",
            "term_start": (term_start or "")[:10],
            "term_end":   (term_end or "")[:10],
            "email":      m.get("Email") or "",
            "phone":      phone,
        })
    columns = [
        {"header": "Name",       "key": "name",       "width": 28, "pdf_width": 2.0},
        {"header": "Position",   "key": "position",   "width": 18, "pdf_width": 1.4},
        {"header": "Term Start", "key": "term_start", "kind": "date", "width": 13, "pdf_width": 1.0},
        {"header": "Term End",   "key": "term_end",   "kind": "date", "width": 13, "pdf_width": 1.0},
        {"header": "Email",      "key": "email",      "width": 30, "pdf_width": 2.0},
        {"header": "Phone",      "key": "phone",      "width": 16, "pdf_width": 1.1},
    ]
    return {
        "columns": columns,
        "rows": rows,
        "totals_row": None,
        "summary": [("Board members", len(rows), "int")],
        "notes": (
            ["No board members configured for this association"] if not rows else None
        ),
        "sheet_name": "Board Roster",
        "landscape": False,
    }


# --------------------------------------------------------------------------
# Cross-validation tie-out checks
#
# Every validator returns a standard cv_data dict:
#
#     {
#         "source_a_label": "Calculated from transactions",
#         "source_b_label": "API: /v1/glaccounts/balances",
#         "rows": [
#             {"item": str, "a": Decimal|str, "b": Decimal|str,
#              "delta": Decimal|str, "status": "MATCH"|"MISMATCH"|"WARNING"},
#             ...
#         ],
#         "has_variances": bool,
#         "notes": [str, ...],   # optional
#     }
#
# Excel writers consume this to build the Cross-Validation tab (first tab in
# every workbook) and to decide whether to stamp a red variance banner on the
# data tab. PDFs are unaffected — cross-validation is Excel-only per spec.
# --------------------------------------------------------------------------

CV_EPSILON = Decimal("0.01")        # "essentially equal" for money comparisons
CV_PERCENT_DEFAULT = Decimal("0.05")  # 5% band for aging-style checks


def _cv_status(
    a: Decimal, b: Decimal,
    *,
    epsilon: Decimal = CV_EPSILON,
    pct_band: Decimal | None = None,
) -> tuple[Decimal, str]:
    """
    Compare two money values. Returns (delta, status).
    - delta = a - b
    - status = MATCH when |delta| <= epsilon
    - if pct_band is provided, status = MATCH when the delta is within pct_band
      of max(|a|, |b|); otherwise MISMATCH.
    """
    delta = a - b
    if abs(delta) <= epsilon:
        return delta, "MATCH"
    if pct_band is not None:
        scale = max(abs(a), abs(b)) or Decimal("1")
        if abs(delta) / scale <= pct_band:
            return delta, "MATCH"
    return delta, "MISMATCH"


def _cv_finalize(rows: list[dict], source_a: str, source_b: str, notes: list[str] | None = None) -> dict:
    """Wrap a list of row dicts into the standard cv_data envelope."""
    has_variances = any(r.get("status") in ("MISMATCH", "WARNING") for r in rows)
    return {
        "source_a_label": source_a,
        "source_b_label": source_b,
        "rows": rows,
        "has_variances": has_variances,
        "notes": notes or [],
    }


def _print_cv_summary(report_type: str, cv_data: dict | None) -> None:
    """ASCII-safe cross-validation summary for stdout (no emoji)."""
    if cv_data is None:
        return
    n_rows = len(cv_data.get("rows") or [])
    n_mm = sum(1 for r in (cv_data.get("rows") or []) if r.get("status") != "MATCH")
    if cv_data.get("has_variances"):
        print(
            f"  cross-validation: [VARIANCES] {n_mm}/{n_rows} row(s) failed",
            flush=True,
        )
    else:
        print(
            f"  cross-validation: [OK] {n_rows} row(s) tied out",
            flush=True,
        )


def _period_activity_from_groups(
    groups: list[tuple[dict, list[dict], Decimal, Decimal]],
    bank_account_ids: set[int] | None = None,
) -> dict[int, Decimal]:
    """
    For each account in `groups`, compute its signed period activity using
    the normal-balance convention: positive means the account moved in its
    natural direction (Asset/Expense += debit, Liability/Equity/Income +=
    credit). This is the same sign convention Buildium uses in its balance
    endpoint, so the two can be compared directly.

    Synthetic cash legs (added by explode_transactions to balance debits
    and credits when Journal.Lines omits the cash side) are normally
    EXCLUDED — they're a report-layer balancing artifact, not real data.

    EXCEPTION: for bank/cash accounts (whose real activity Buildium reports
    via /bankaccounts/{id}/transactions, not via Journal.Lines on the GL
    endpoint), synth legs ARE the only representation of bank activity in
    our pool. Including them lets the bank account totals reconcile to the
    balance endpoint instead of always reading $0.
    """
    bank_ids = bank_account_ids or set()
    out: dict[int, Decimal] = {}
    for acct, lines, _td, _tc in groups:
        aid = acct.get("Id")
        if aid is None:
            continue
        include_synth = aid in bank_ids
        if include_synth:
            real_td = sum((l["debit"]  for l in lines), ZERO)
            real_tc = sum((l["credit"] for l in lines), ZERO)
        else:
            real_td = sum((l["debit"]  for l in lines if not l.get("synthetic")), ZERO)
            real_tc = sum((l["credit"] for l in lines if not l.get("synthetic")), ZERO)
        t = acct.get("Type")
        if t in ("Liability", "Equity", "Income"):
            out[aid] = real_tc - real_td  # credit-normal
        else:
            out[aid] = real_td - real_tc  # Asset, Expense, and default
    return out


def validate_general_ledger(
    groups: list,
    gl_activity_api: dict[int, Decimal],
    bank_account_ids: set[int] | None = None,
) -> dict:
    """
    Per-account: compare period activity computed from transactions vs
    period activity computed from (API closing balance - API opening balance).
    Flags any delta > $0.01.

    bank_account_ids — set of GL account ids whose real activity comes from
    synthesized cash legs (because Buildium's Journal.Lines omits the cash
    side). Passing this set lets the validator include synth legs for those
    accounts so bank totals reconcile to the API.
    """
    calc = _period_activity_from_groups(groups, bank_account_ids)
    rows: list[dict] = []
    for acct, _lines, _td, _tc in sorted(groups, key=lambda g: (g[0].get("AccountNumber") or "", g[0].get("Name") or "")):
        aid = acct.get("Id")
        if aid is None:
            continue
        a = calc.get(aid, ZERO)
        b = gl_activity_api.get(aid, ZERO)
        delta, status = _cv_status(a, b)
        item = f"{acct.get('AccountNumber','?')}  {acct.get('Name','')}".strip()
        rows.append({"item": item, "a": a, "b": b, "delta": delta, "status": status})
    notes = None
    if not gl_activity_api:
        notes = ["API balance endpoint returned no data; all API-side values shown as $0."]
    return _cv_finalize(
        rows,
        "Per-txn calc  (tx.debits − tx.credits)",
        "API  (closing − opening balance)",
        notes,
    )


def validate_income_statement(
    is_data: dict,
    gl_activity_api: dict[int, Decimal],
    accounts: dict[int, dict],
) -> dict:
    """
    Cross-validate Income Statement against /v1/glaccounts/balances.

    Source of truth = Buildium balance endpoint (fetch_gl_balances_period).
    For Income accounts the period activity is credit-normal (positive =
    income earned). For Expense accounts it's debit-normal (positive =
    expense incurred). We sum each side from the API snapshot and compare
    to the script's own reported totals.

    Also retains the internal arithmetic check (Net Income = Revenue −
    Expenses) so a builder bug shows up as a third row.
    """
    reported_rev = _to_decimal(is_data.get("total_revenue"))
    reported_exp = _to_decimal(is_data.get("total_expenses"))
    reported_ni  = _to_decimal(is_data.get("net_income"))

    api_rev = ZERO
    api_exp = ZERO
    for aid, activity in (gl_activity_api or {}).items():
        a = accounts.get(aid) or {}
        t = a.get("Type")
        if t == "Income":
            api_rev += activity
        elif t == "Expense":
            api_exp += activity
    api_ni = api_rev - api_exp

    rows = []
    for label, a, b in (
        ("Total Revenue",  reported_rev, api_rev),
        ("Total Expenses", reported_exp, api_exp),
        ("Net Income",     reported_ni,  api_ni),
    ):
        delta, status = _cv_status(a, b)
        rows.append({"item": label, "a": a, "b": b, "delta": delta, "status": status})

    notes = None
    if not gl_activity_api:
        notes = ["API balance endpoint returned no data; all API-side values shown as $0."]

    return _cv_finalize(
        rows,
        "Reported (script calc)",
        "API  (closing − opening balance)",
        notes,
    )


def validate_balance_sheet(
    bs_data: dict,
    gl_balances_close: dict[int, Decimal],
    accounts: dict[int, dict],
) -> dict:
    """
    Cross-validate Balance Sheet against /v1/glaccounts/balances closing
    snapshot. The API returns each account in its normal-balance direction
    (positive = natural-side balance), so we can sum by account Type
    directly without sign flips.

    Also retains the internal accounting-equation check
    (Assets = Liabilities + Equity).
    """
    reported_ta = _to_decimal(bs_data.get("total_assets"))
    reported_tl = _to_decimal(bs_data.get("total_liabilities"))
    reported_te = _to_decimal(bs_data.get("total_equity"))
    reported_lpe = _to_decimal(bs_data.get("liab_plus_equity"))

    api_ta = ZERO
    api_tl = ZERO
    api_te = ZERO
    for aid, bal in (gl_balances_close or {}).items():
        a = accounts.get(aid) or {}
        t = a.get("Type")
        if t == "Asset":
            api_ta += bal
        elif t == "Liability":
            api_tl += bal
        elif t == "Equity":
            api_te += bal

    # Buildium's balance endpoint doesn't roll Income−Expenses into Equity
    # within-period (Current Period Earnings is a script construct), so we
    # add it on the API side too for an apples-to-apples comparison.
    cpe = _to_decimal(bs_data.get("current_period_earnings"))
    api_te_with_cpe = api_te + cpe
    api_lpe = api_tl + api_te_with_cpe

    rows = []
    for label, a, b in (
        ("Total Assets",            reported_ta, api_ta),
        ("Total Liabilities",       reported_tl, api_tl),
        ("Total Equity (incl CPE)", reported_te, api_te_with_cpe),
        ("Assets = Liab + Equity",  reported_ta, api_lpe),
    ):
        delta, status = _cv_status(a, b)
        rows.append({"item": label, "a": a, "b": b, "delta": delta, "status": status})

    notes = None
    if not gl_balances_close:
        notes = ["API balance endpoint returned no data; all API-side values shown as $0."]

    return _cv_finalize(
        rows,
        "Reported (script calc)",
        "API  (closing balance snapshot)",
        notes,
    )


def validate_trial_balance(
    groups: list,
    gl_activity_api: dict[int, Decimal],
    bank_account_ids: set[int] | None = None,
) -> dict:
    """
    Per-account: compare real-only TB net against API period activity.

    Uses _period_activity_from_groups, which excludes synthetic cash legs
    EXCEPT for accounts in bank_account_ids (where synth legs are the only
    representation of bank activity). Both sides are converted to debit-
    positive form for a sign-consistent comparison.
    """
    real_activity = _period_activity_from_groups(groups, bank_account_ids)
    rows: list[dict] = []
    for acct, _lines, _td, _tc in groups:
        aid = acct.get("Id")
        if aid is None:
            continue
        t = acct.get("Type", "")
        a_normal = real_activity.get(aid, ZERO)
        b_normal = gl_activity_api.get(aid, ZERO)
        # Convert normal-balance form to debit-positive for both sides
        if t in ("Liability", "Equity", "Income"):
            a_dp, b_dp = -a_normal, -b_normal
        else:
            a_dp, b_dp = a_normal, b_normal
        delta, status = _cv_status(a_dp, b_dp)
        item = f"{acct.get('AccountNumber','?')}  {acct.get('Name','')}".strip()
        rows.append({"item": item, "a": a_dp, "b": b_dp, "delta": delta, "status": status})
    rows.sort(key=lambda r: r["item"])
    return _cv_finalize(
        rows,
        "TB net real lines only (debit − credit)",
        "API  (closing − opening, debit-positive)",
    )


def validate_ap_aging(
    ap_total: Decimal,
    gl_balances_accrual_end: dict[int, Decimal],
    accounts: dict[int, dict],
) -> dict:
    """
    AP aging total vs GL Accounts Payable balance. 5% band.

    AP is structurally an Accrual concept — bills become liabilities the
    moment they're received, regardless of whether they've been paid in
    cash. On Cash basis, the GL Accounts Payable balance is always $0
    (bills only hit the books when cash moves), so comparing an AP
    aging report against a Cash-basis AP balance is a category error.

    We therefore ALWAYS pass an Accrual-basis balance dict in here,
    regardless of the user's --basis flag. The caller (main / batch)
    fetches a one-off Accrual snapshot just for this validator if the
    report basis is Cash.
    """
    ap_acct_id = None
    for aid, a in accounts.items():
        nm = (a.get("Name") or "").strip().lower()
        num = (a.get("AccountNumber") or "").strip()
        if nm == "accounts payable" or num == "20000":
            ap_acct_id = aid
            break
    if ap_acct_id is None:
        return _cv_finalize(
            [{"item": "Accounts Payable GL lookup", "a": "—", "b": "—", "delta": "—", "status": "WARNING"}],
            "AP aging unpaid-bill total",
            "GL Accounts Payable balance (Accrual)",
            notes=["Could not locate the Accounts Payable account in the chart of accounts."],
        )
    gl_ap = gl_balances_accrual_end.get(ap_acct_id, ZERO)
    delta, status = _cv_status(ap_total, gl_ap, pct_band=CV_PERCENT_DEFAULT)
    return _cv_finalize(
        [
            {"item": "Total open AP (unpaid bills)", "a": ap_total, "b": gl_ap, "delta": delta, "status": status},
        ],
        "AP aging report",
        "GL Accounts Payable balance (always Accrual, even on Cash-basis runs)",
        notes=[
            "Accounts Payable is intrinsically an accrual concept; on Cash basis the GL AP "
            "balance is always $0. This validator always fetches AP at Accrual basis "
            "regardless of --basis, so the comparison is meaningful.",
        ],
    )


def validate_check_register(checks: list[dict], bank_txns: list[dict]) -> dict:
    """
    Every check from /bankaccounts/{id}/checks should have a matching
    row in /bankaccounts/{id}/transactions.

    Discovered via probe (2026-04-16): each check and its corresponding
    bank transaction share the SAME Buildium Id. Bank txn amounts are
    NEGATIVE for outflows (e.g. a $2000 check is amount=-2000.0 on the
    bank side). My original matcher used (date, positive_amount) which
    failed 100% of the time because it couldn't see past the sign flip.

    Fix: match by Id (the canonical, exact match). Fall back to
    (date, abs(amount)) for cases where the IDs ever diverge so we don't
    silently miss a legitimately-paired record.
    """
    bank_ids = {t.get("Id") for t in bank_txns if t.get("Id") is not None}
    bank_by_date_amt: dict[tuple, int] = {}
    for t in bank_txns:
        entry_date = (t.get("EntryDate") or "")[:10]
        amt_abs = abs(_to_decimal(t.get("Amount")))
        key = (entry_date, amt_abs)
        bank_by_date_amt[key] = bank_by_date_amt.get(key, 0) + 1

    matched_by_id = 0
    matched_by_fallback = 0
    orphans = 0
    for c in checks:
        cid = c.get("Id")
        if cid in bank_ids:
            matched_by_id += 1
            continue
        check_date = (c.get("EntryDate") or "")[:10]
        check_amt_abs = abs(_to_decimal(c.get("TotalAmount")))
        key = (check_date, check_amt_abs)
        if bank_by_date_amt.get(key, 0) > 0:
            bank_by_date_amt[key] -= 1
            matched_by_fallback += 1
        else:
            orphans += 1

    matched_total = matched_by_id + matched_by_fallback
    rows: list[dict] = [
        {
            "item": "Checks matched to a bank transaction",
            "a": Decimal(matched_total),
            "b": Decimal(len(checks)),
            "delta": Decimal(matched_total - len(checks)),
            "status": "MATCH" if orphans == 0 else "MISMATCH",
        },
        {
            "item": "  ... matched by Id (exact)",
            "a": Decimal(matched_by_id), "b": "—", "delta": "—", "status": "MATCH",
        },
        {
            "item": "  ... matched by (date, abs(amount)) fallback",
            "a": Decimal(matched_by_fallback), "b": "—", "delta": "—",
            "status": "MATCH" if matched_by_fallback == 0 else "WARNING",
        },
        {
            "item": "Orphan checks (no matching bank txn)",
            "a": Decimal(orphans),
            "b": Decimal(0),
            "delta": Decimal(orphans),
            "status": "MATCH" if orphans == 0 else "MISMATCH",
        },
    ]
    return _cv_finalize(
        rows,
        "Check register",
        "Bank transactions",
        notes=[
            "Primary match: Buildium Id (checks and their bank-side row share the same Id).",
            "Fallback match: (entry_date, abs(amount)) — used only if Id matching misses.",
            "Bank transaction Amount field is NEGATIVE for outflows; matching on absolute value.",
        ],
    )


def validate_ar_aging(
    outstanding: list[dict],
    headers: dict,
    association_id: int,
    start_date: str,
    end_date: str,
) -> dict:
    """
    For each ownership account with an outstanding balance, compare the
    Balance-endpoint total against (charges − payments) from that owner's
    transaction history in the period. Expensive (N API calls) — scoped to
    rows that actually have a balance.
    """
    rows: list[dict] = []
    for b in outstanding:
        oa_id = b.get("OwnershipAccountId")
        api_total = _to_decimal(b.get("TotalBalance"))
        if oa_id is None or api_total == ZERO:
            continue
        try:
            txns = fetch_ownership_account_transactions(headers, oa_id, start_date, end_date)
        except SystemExit as e:
            rows.append({
                "item": f"Ownership acct {oa_id}",
                "a": api_total, "b": "—", "delta": "—", "status": "WARNING",
            })
            continue
        # Negative TotalAmount = payment; positive = charge.
        charges = ZERO
        payments = ZERO
        for t in txns:
            amt = _to_decimal(t.get("TotalAmount"))
            if amt >= ZERO:
                charges += amt
            else:
                payments += -amt
        calc_net = charges - payments
        delta, status = _cv_status(api_total, calc_net)
        rows.append({
            "item": f"Ownership acct {oa_id}",
            "a": api_total, "b": calc_net, "delta": delta, "status": status,
        })
    if not rows:
        rows.append({
            "item": "No outstanding balances to validate",
            "a": "—", "b": "—", "delta": "—", "status": "MATCH",
        })
    return _cv_finalize(
        rows,
        "Outstanding Balances API",
        "Charges − Payments (owner txns)",
    )


def validate_bank_register(
    bank_reg_ending: Decimal,
    gl_balances_end: dict[int, Decimal],
    operating_bank_id: int | None,
) -> dict:
    """Register ending balance vs GL bank account balance."""
    if operating_bank_id is None:
        return _cv_finalize(
            [{"item": "Bank account", "a": "—", "b": "—", "delta": "—", "status": "WARNING"}],
            "Bank register",
            "GL bank balance",
            notes=["Association has no OperatingBankAccountId — cannot validate."],
        )
    gl_bank = gl_balances_end.get(operating_bank_id, ZERO)
    delta, status = _cv_status(bank_reg_ending, gl_bank)
    return _cv_finalize(
        [
            {"item": f"Operating bank (#{operating_bank_id}) ending balance", "a": bank_reg_ending, "b": gl_bank, "delta": delta, "status": status},
        ],
        "Bank register (last running balance)",
        "GL account balance (as of end_date)",
    )


def validate_vendor_payment_summary(
    vendor_total: Decimal, check_total: Decimal,
) -> dict:
    """Vendor payment total vs check register total. 5% band."""
    delta, status = _cv_status(vendor_total, check_total, pct_band=CV_PERCENT_DEFAULT)
    return _cv_finalize(
        [
            {"item": "Total vendor payments vs total checks written", "a": vendor_total, "b": check_total, "delta": delta, "status": status},
        ],
        "Vendor payment summary",
        "Check register",
        notes=["Check register includes all checks regardless of vendor/non-vendor payee; some drift is expected."],
    )


def validate_budget_vs_actual(
    budget: dict | None, groups: list, accounts: dict[int, dict],
) -> dict:
    """Every budget line has a chart account; flag actuals with no budget line."""
    rows: list[dict] = []
    budget_ids: set[int] = set()
    for d in (budget or {}).get("Details") or []:
        gid = d.get("GLAccountId")
        if gid is not None:
            budget_ids.add(gid)

    # Budget lines with no matching chart account
    orphan_budget = [gid for gid in budget_ids if gid not in accounts]
    rows.append({
        "item": "Budget lines with matching GL account",
        "a": Decimal(len(budget_ids) - len(orphan_budget)),
        "b": Decimal(len(budget_ids)),
        "delta": Decimal(-len(orphan_budget)),
        "status": "MATCH" if not orphan_budget else "MISMATCH",
    })

    # P&L accounts with actual activity but no budget line
    actuals_pl_ids: set[int] = set()
    for acct, _lines, td, tc in groups:
        if acct.get("Type") in ("Income", "Expense") and (td != ZERO or tc != ZERO):
            actuals_pl_ids.add(acct.get("Id"))
    unbudgeted = [gid for gid in actuals_pl_ids if gid not in budget_ids]
    rows.append({
        "item": "P&L accounts with activity but no budget",
        "a": Decimal(len(unbudgeted)),
        "b": Decimal(0),
        "delta": Decimal(len(unbudgeted)),
        "status": "MATCH" if not unbudgeted else "WARNING",
    })

    notes = []
    if orphan_budget:
        notes.append(f"Orphan budget GL ids: {orphan_budget[:10]}")
    if unbudgeted:
        # Look up a few names for context
        names = [accounts.get(g, {}).get("Name", f"({g})") for g in unbudgeted[:6]]
        notes.append(f"Unbudgeted P&L accounts (up to 6): {', '.join(names)}")

    return _cv_finalize(
        rows,
        "Budget line count",
        "Chart of accounts / actuals",
        notes=notes,
    )


# --------------------------------------------------------------------------
# Excel output
# --------------------------------------------------------------------------

CURRENCY_FMT = '"$"#,##0.00;[Red]-"$"#,##0.00'
# Daisy brand colors (hex without leading '#', as openpyxl expects).
HEADER_FILL = PatternFill("solid", fgColor="1B4332")   # hunter green
HEADER_FONT = Font(bold=True, color="FFFFFF")
SECTION_FILL = PatternFill("solid", fgColor="1B4332")  # hunter green
SECTION_FONT = Font(bold=True, color="FFFFFF")

# Variance banner / status colors
VARIANCE_FILL = PatternFill("solid", fgColor="9C0006")  # red
MATCH_COLOR = "006100"    # green text for MATCH cells
MISMATCH_COLOR = "9C0006"  # red text for MISMATCH/WARNING


def _cv_cell_value(value: Any) -> Any:
    """Cross-validation cells: coerce Decimal to float, leave strings alone."""
    if value is None or value == "":
        return None
    if isinstance(value, Decimal):
        return float(value)
    if isinstance(value, (int, float)):
        return float(value)
    return str(value)


def _write_cross_validation_tab(
    ws,
    building: str,
    association_id: int,
    report_title: str,
    start_date: str,
    end_date: str,
    cv_data: dict | None,
) -> None:
    """
    Populate the Cross-Validation tab of a workbook using the standard
    cv_data envelope produced by the validator functions. Columns:

        Item | <Source A label> | <Source B label> | Delta | Status

    A final summary row shows:
        ✅  ALL TIED OUT       (no variances)
        ❌  VARIANCES FOUND    (one or more MISMATCH/WARNING rows)

    If `cv_data` is None, the tab still exists but contains a "not run"
    note so every workbook has a consistent first-tab shape.
    """
    # Title block
    ws["A1"] = "Daisy Living"
    ws["A1"].font = Font(bold=True, size=16)
    ws["A2"] = building
    ws["A2"].font = Font(bold=True, size=12)
    ws["A3"] = f"Cross-Validation  |  {report_title}  |  {start_date} to {end_date}  |  Basis: {_BASIS}"
    ws["A4"] = (
        f"Association ID: {association_id}  |  "
        f"Generated: {datetime.now():%Y-%m-%d %H:%M}"
    )
    ws["A4"].font = Font(italic=True, size=9)

    if cv_data is None:
        note = ws.cell(row=6, column=1, value="(cross-validation not run for this report type)")
        note.font = Font(italic=True, size=10, color="808080")
        ws.column_dimensions["A"].width = 60
        return

    src_a = cv_data.get("source_a_label", "Source A")
    src_b = cv_data.get("source_b_label", "Source B")

    # Column headers
    headers_row = ["Item", src_a, src_b, "Delta", "Status"]
    for i, h in enumerate(headers_row, start=1):
        c = ws.cell(row=6, column=i, value=h)
        c.font = HEADER_FONT
        c.fill = HEADER_FILL
        c.alignment = Alignment(horizontal="center")

    row = 7
    for r in cv_data.get("rows") or []:
        item_cell = ws.cell(row=row, column=1, value=r.get("item", ""))
        a_cell = ws.cell(row=row, column=2, value=_cv_cell_value(r.get("a")))
        b_cell = ws.cell(row=row, column=3, value=_cv_cell_value(r.get("b")))
        delta_cell = ws.cell(row=row, column=4, value=_cv_cell_value(r.get("delta")))
        status = r.get("status", "?")
        status_cell = ws.cell(row=row, column=5, value=status)

        # Format money columns
        for c in (a_cell, b_cell, delta_cell):
            if isinstance(c.value, float):
                c.number_format = CURRENCY_FMT
                c.alignment = Alignment(horizontal="right")

        # Color the status cell
        if status == "MATCH":
            status_cell.font = Font(bold=True, color=MATCH_COLOR)
        else:
            status_cell.font = Font(bold=True, color=MISMATCH_COLOR)
        status_cell.alignment = Alignment(horizontal="center")

        # Tint the whole row's delta column red on mismatch
        if status != "MATCH" and isinstance(delta_cell.value, float):
            delta_cell.font = Font(bold=True, color=MISMATCH_COLOR)

        row += 1

    # Summary row — at least 1 blank row then the summary banner
    row += 1
    has_variances = bool(cv_data.get("has_variances"))
    summary_text = (
        "❌  VARIANCES FOUND" if has_variances else "✅  ALL TIED OUT"
    )
    sc = ws.cell(row=row, column=1, value=summary_text)
    sc.font = Font(bold=True, size=13, color="FFFFFF")
    sc.fill = VARIANCE_FILL if has_variances else PatternFill("solid", fgColor=MATCH_COLOR)
    ws.merge_cells(start_row=row, start_column=1, end_row=row, end_column=5)
    ws.row_dimensions[row].height = 24
    row += 1

    # Optional notes below
    notes = cv_data.get("notes") or []
    for note in notes:
        row += 1
        nc = ws.cell(row=row, column=1, value=f"Note: {note}")
        nc.font = Font(italic=True, size=9, color="808080")
        ws.merge_cells(start_row=row, start_column=1, end_row=row, end_column=5)

    # Column widths
    ws.column_dimensions["A"].width = 48
    ws.column_dimensions["B"].width = 22
    ws.column_dimensions["C"].width = 22
    ws.column_dimensions["D"].width = 16
    ws.column_dimensions["E"].width = 12
    ws.freeze_panes = "A7"


def _prepend_variance_banner(ws, num_cols: int) -> None:
    """
    Insert a red variance banner as the new row 1, shifting existing content
    down by one row. Called from data tabs when cv_data.has_variances is True.
    """
    ws.insert_rows(1)
    cell = ws.cell(
        row=1, column=1,
        value="⚠  VARIANCES FOUND — see Cross-Validation tab",
    )
    cell.font = Font(bold=True, color="FFFFFF", size=12)
    cell.fill = VARIANCE_FILL
    cell.alignment = Alignment(horizontal="center", vertical="center")
    if num_cols > 1:
        ws.merge_cells(start_row=1, start_column=1, end_row=1, end_column=num_cols)
    ws.row_dimensions[1].height = 24


def write_excel_gl(
    path: Path,
    building: str,
    association_id: int,
    start_date: str,
    end_date: str,
    groups: list[tuple[dict, list[dict], Decimal, Decimal]],
    total_debit: Decimal,
    total_credit: Decimal,
    cv_data: dict | None = None,
) -> None:
    wb = Workbook()

    # Cross-Validation as first tab
    cv = wb.active
    cv.title = "Cross-Validation"
    _write_cross_validation_tab(
        cv, building, association_id, "General Ledger", start_date, end_date, cv_data,
    )

    ws = wb.create_sheet("General Ledger")

    # Title block
    ws["A1"] = "Daisy Living"
    ws["A1"].font = Font(bold=True, size=16)
    ws["A2"] = building
    ws["A2"].font = Font(bold=True, size=12)
    ws["A3"] = f"General Ledger  |  {start_date} to {end_date}  |  Basis: {_BASIS}"
    ws["A4"] = f"Association ID: {association_id}  |  Generated: {datetime.now():%Y-%m-%d %H:%M}"
    ws["A4"].font = Font(italic=True, size=9)

    headers = ["Date", "Txn Type", "Txn ID", "Memo", "Debit", "Credit", "Balance"]
    header_row = 6
    for i, h in enumerate(headers, start=1):
        c = ws.cell(row=header_row, column=i, value=h)
        c.font = HEADER_FONT
        c.fill = HEADER_FILL
        c.alignment = Alignment(horizontal="center")

    row = header_row + 1
    for acct, lines, td, tc in groups:
        # Section header row
        label = f"{acct.get('AccountNumber','')}  {acct.get('Name','')}  ({acct.get('Type','')})"
        cell = ws.cell(row=row, column=1, value=label.strip())
        cell.font = SECTION_FONT
        cell.fill = SECTION_FILL
        for col in range(2, 8):
            ws.cell(row=row, column=col).fill = SECTION_FILL
        row += 1

        balance = ZERO
        for line in lines:
            balance += line["debit"] - line["credit"]
            ws.cell(row=row, column=1, value=line["date"])
            ws.cell(row=row, column=2, value=line["txn_type"])
            ws.cell(row=row, column=3, value=line["txn_id"])
            ws.cell(row=row, column=4, value=str(line["memo"])[:200])
            d = ws.cell(row=row, column=5, value=float(line["debit"]) if line["debit"] else None)
            c = ws.cell(row=row, column=6, value=float(line["credit"]) if line["credit"] else None)
            b = ws.cell(row=row, column=7, value=float(balance))
            for cell in (d, c, b):
                cell.number_format = CURRENCY_FMT
            row += 1

        # Subtotal row -- green bar across the right side of the row
        subtotal_label = ws.cell(row=row, column=4, value="Subtotal:")
        subtotal_label.font = SECTION_FONT
        subtotal_label.fill = SECTION_FILL
        subtotal_label.alignment = Alignment(horizontal="right")
        for col_idx, val in ((5, td), (6, tc), (7, td - tc)):
            c = ws.cell(row=row, column=col_idx, value=float(val))
            c.number_format = CURRENCY_FMT
            c.font = SECTION_FONT
            c.fill = SECTION_FILL
        row += 2  # blank row between accounts

    # Grand total -- same green treatment, larger font
    gt_label = ws.cell(row=row, column=4, value="GRAND TOTAL:")
    gt_label.font = Font(bold=True, size=12, color="FFFFFF")
    gt_label.fill = SECTION_FILL
    gt_label.alignment = Alignment(horizontal="right")
    for col_idx, val in ((5, total_debit), (6, total_credit), (7, total_debit - total_credit)):
        c = ws.cell(row=row, column=col_idx, value=float(val))
        c.number_format = CURRENCY_FMT
        c.font = Font(bold=True, size=12, color="FFFFFF")
        c.fill = SECTION_FILL

    # Column widths
    widths = {1: 12, 2: 18, 3: 10, 4: 50, 5: 14, 6: 14, 7: 16}
    for col, w in widths.items():
        ws.column_dimensions[get_column_letter(col)].width = w

    ws.freeze_panes = "A7"

    # Summary tab
    s = wb.create_sheet("Summary")
    s["A1"] = "Daisy Living"
    s["A1"].font = Font(bold=True, size=16)
    s["A2"] = building
    s["A3"] = f"General Ledger  |  {start_date} to {end_date}  |  Basis: {_BASIS}"
    s["A5"] = "Accounts with activity"
    s["B5"] = len(groups)
    s["A6"] = "Total debits"
    s["B6"] = float(total_debit)
    s["B6"].number_format = CURRENCY_FMT
    s["A7"] = "Total credits"
    s["B7"] = float(total_credit)
    s["B7"].number_format = CURRENCY_FMT
    s["A8"] = "Net (debits - credits)"
    s["B8"] = float(total_debit - total_credit)
    s["B8"].number_format = CURRENCY_FMT
    s.column_dimensions["A"].width = 28
    s.column_dimensions["B"].width = 18

    if cv_data and cv_data.get("has_variances"):
        _prepend_variance_banner(ws, num_cols=7)

    wb.save(path)


def _excel_title_block(
    ws, building: str, association_id: int, report_title: str,
    start_date: str, end_date: str,
) -> None:
    ws["A1"] = "Daisy Living"
    ws["A1"].font = Font(bold=True, size=16)
    ws["A2"] = building
    ws["A2"].font = Font(bold=True, size=12)
    ws["A3"] = f"{report_title}  |  {start_date} to {end_date}  |  Basis: {_BASIS}"
    ws["A4"] = (
        f"Association ID: {association_id}  |  "
        f"Generated: {datetime.now():%Y-%m-%d %H:%M}"
    )
    ws["A4"].font = Font(italic=True, size=9)


def write_excel_is(
    path: Path,
    building: str,
    association_id: int,
    start_date: str,
    end_date: str,
    is_data: dict,
    cv_data: dict | None = None,
) -> None:
    wb = Workbook()
    cv = wb.active
    cv.title = "Cross-Validation"
    _write_cross_validation_tab(
        cv, building, association_id, "Income Statement", start_date, end_date, cv_data,
    )
    ws = wb.create_sheet("Income Statement")
    _excel_title_block(ws, building, association_id, "Income Statement", start_date, end_date)

    for i, h in enumerate(["Account #", "Account Name", "Amount"], start=1):
        c = ws.cell(row=6, column=i, value=h)
        c.font = HEADER_FONT
        c.fill = HEADER_FILL
        c.alignment = Alignment(horizontal="center")
    row = 7

    def section(title: str, rows: list[tuple[dict, Decimal]], total_label: str, total_val: Decimal) -> None:
        nonlocal row
        cell = ws.cell(row=row, column=1, value=title)
        cell.font = Font(bold=True, size=12, color="FFFFFF")
        for col in range(1, 4):
            ws.cell(row=row, column=col).fill = SECTION_FILL
        row += 1
        for acct, amt in rows:
            ws.cell(row=row, column=1, value=acct.get("AccountNumber") or "")
            ws.cell(row=row, column=2, value=acct.get("Name") or "")
            c = ws.cell(row=row, column=3, value=float(amt))
            c.number_format = CURRENCY_FMT
            row += 1
        tlabel = ws.cell(row=row, column=2, value=total_label)
        tlabel.font = SECTION_FONT
        tlabel.fill = SECTION_FILL
        tlabel.alignment = Alignment(horizontal="right")
        tv = ws.cell(row=row, column=3, value=float(total_val))
        tv.font = SECTION_FONT
        tv.fill = SECTION_FILL
        tv.number_format = CURRENCY_FMT
        row += 2

    section("REVENUE", is_data["revenue"], "Total Revenue", is_data["total_revenue"])
    section("EXPENSES", is_data["expenses"], "Total Expenses", is_data["total_expenses"])

    ni_label = ws.cell(row=row, column=2, value="NET INCOME")
    ni_label.font = Font(bold=True, size=13, color="FFFFFF")
    ni_label.fill = SECTION_FILL
    ni_label.alignment = Alignment(horizontal="right")
    ni_val = ws.cell(row=row, column=3, value=float(is_data["net_income"]))
    ni_val.font = Font(bold=True, size=13, color="FFFFFF")
    ni_val.fill = SECTION_FILL
    ni_val.number_format = CURRENCY_FMT

    ws.column_dimensions["A"].width = 14
    ws.column_dimensions["B"].width = 55
    ws.column_dimensions["C"].width = 18
    ws.freeze_panes = "A7"

    # Summary tab
    s = wb.create_sheet("Summary")
    s["A1"] = "Daisy Living"
    s["A1"].font = Font(bold=True, size=16)
    s["A2"] = building
    s["A3"] = f"Income Statement  |  {start_date} to {end_date}  |  Basis: {_BASIS}"
    s["A5"] = "Total Revenue"
    s["B5"] = float(is_data["total_revenue"])
    s["A6"] = "Total Expenses"
    s["B6"] = float(is_data["total_expenses"])
    s["A7"] = "Net Income"
    s["B7"] = float(is_data["net_income"])
    for cell in ("B5", "B6", "B7"):
        s[cell].number_format = CURRENCY_FMT
    s["B7"].font = Font(bold=True)
    s.column_dimensions["A"].width = 22
    s.column_dimensions["B"].width = 18

    if cv_data and cv_data.get("has_variances"):
        _prepend_variance_banner(ws, num_cols=3)

    wb.save(path)


def write_excel_bs(
    path: Path,
    building: str,
    association_id: int,
    start_date: str,
    end_date: str,
    bs_data: dict,
    cv_data: dict | None = None,
) -> None:
    wb = Workbook()
    cv = wb.active
    cv.title = "Cross-Validation"
    _write_cross_validation_tab(
        cv, building, association_id, "Balance Sheet", start_date, end_date, cv_data,
    )
    ws = wb.create_sheet("Balance Sheet")
    _excel_title_block(ws, building, association_id, "Balance Sheet", start_date, end_date)
    note = ws.cell(
        row=5, column=1,
        value="Period activity only (opening balances assumed $0 on start date)",
    )
    note.font = Font(italic=True, size=9, color="808080")

    for i, h in enumerate(["Account #", "Account Name", "Balance"], start=1):
        c = ws.cell(row=7, column=i, value=h)
        c.font = HEADER_FONT
        c.fill = HEADER_FILL
        c.alignment = Alignment(horizontal="center")
    row = 8

    def section(title: str, section_data: dict, total_label: str, total_val: Decimal) -> None:
        nonlocal row
        cell = ws.cell(row=row, column=1, value=title)
        cell.font = Font(bold=True, size=13, color="FFFFFF")
        for col in range(1, 4):
            ws.cell(row=row, column=col).fill = SECTION_FILL
        row += 1
        for sub, rows_ in section_data.items():
            # Sub-type rows stay plain (italic bold black on white) so the
            # visual hierarchy remains: green bars for top-level sections,
            # italic headings for sub-types, plain rows for accounts.
            sub_cell = ws.cell(row=row, column=1, value=f"  {sub}")
            sub_cell.font = Font(bold=True, italic=True, size=10)
            row += 1
            sub_total = ZERO
            for acct, amt in rows_:
                ws.cell(row=row, column=1, value=acct.get("AccountNumber") or "")
                ws.cell(row=row, column=2, value=f"    {acct.get('Name') or ''}")
                c = ws.cell(row=row, column=3, value=float(amt))
                c.number_format = CURRENCY_FMT
                sub_total += amt
                row += 1
            stl = ws.cell(row=row, column=2, value=f"Subtotal - {sub}")
            stl.font = Font(italic=True, bold=True)
            stl.alignment = Alignment(horizontal="right")
            stv = ws.cell(row=row, column=3, value=float(sub_total))
            stv.number_format = CURRENCY_FMT
            stv.font = Font(italic=True, bold=True)
            row += 1
        tlabel = ws.cell(row=row, column=2, value=total_label)
        tlabel.font = SECTION_FONT
        tlabel.fill = SECTION_FILL
        tlabel.alignment = Alignment(horizontal="right")
        tv = ws.cell(row=row, column=3, value=float(total_val))
        tv.font = SECTION_FONT
        tv.number_format = CURRENCY_FMT
        tv.fill = SECTION_FILL
        row += 2

    section("ASSETS", bs_data["assets"], "TOTAL ASSETS", bs_data["total_assets"])
    section("LIABILITIES", bs_data["liabilities"], "Total Liabilities", bs_data["total_liabilities"])
    section("EQUITY", bs_data["equity"], "Total Equity", bs_data["total_equity"])

    lpe = ws.cell(row=row, column=2, value="TOTAL LIABILITIES + EQUITY")
    lpe.font = Font(bold=True, size=12, color="FFFFFF")
    lpe.fill = SECTION_FILL
    lpe.alignment = Alignment(horizontal="right")
    lpe_v = ws.cell(row=row, column=3, value=float(bs_data["liab_plus_equity"]))
    lpe_v.font = Font(bold=True, size=12, color="FFFFFF")
    lpe_v.fill = SECTION_FILL
    lpe_v.number_format = CURRENCY_FMT
    row += 2

    chk = ws.cell(
        row=row, column=2,
        value=("BALANCES ✓" if bs_data["balances"] else "DOES NOT BALANCE"),
    )
    chk.font = Font(bold=True, size=10, color=("006100" if bs_data["balances"] else "9C0006"))
    chk.alignment = Alignment(horizontal="right")
    delta = bs_data["total_assets"] - bs_data["liab_plus_equity"]
    dv = ws.cell(row=row, column=3, value=float(delta))
    dv.number_format = CURRENCY_FMT
    dv.font = Font(bold=True, color=("006100" if bs_data["balances"] else "9C0006"))

    ws.column_dimensions["A"].width = 14
    ws.column_dimensions["B"].width = 55
    ws.column_dimensions["C"].width = 18
    ws.freeze_panes = "A8"

    s = wb.create_sheet("Summary")
    s["A1"] = "Daisy Living"
    s["A1"].font = Font(bold=True, size=16)
    s["A2"] = building
    s["A3"] = f"Balance Sheet  |  {start_date} to {end_date}  |  Basis: {_BASIS}"
    s["A5"] = "Total Assets"
    s["B5"] = float(bs_data["total_assets"])
    s["A6"] = "Total Liabilities"
    s["B6"] = float(bs_data["total_liabilities"])
    s["A7"] = "Total Equity"
    s["B7"] = float(bs_data["total_equity"])
    s["A8"] = "Liabilities + Equity"
    s["B8"] = float(bs_data["liab_plus_equity"])
    s["A9"] = "Balance check (A - L - E)"
    s["B9"] = float(bs_data["total_assets"] - bs_data["liab_plus_equity"])
    for cell in ("B5", "B6", "B7", "B8", "B9"):
        s[cell].number_format = CURRENCY_FMT
    s.column_dimensions["A"].width = 26
    s.column_dimensions["B"].width = 18

    if cv_data and cv_data.get("has_variances"):
        _prepend_variance_banner(ws, num_cols=3)

    wb.save(path)


def write_excel_tb(
    path: Path,
    building: str,
    association_id: int,
    start_date: str,
    end_date: str,
    tb_data: dict,
    cv_data: dict | None = None,
) -> None:
    wb = Workbook()
    cv = wb.active
    cv.title = "Cross-Validation"
    _write_cross_validation_tab(
        cv, building, association_id, "Trial Balance", start_date, end_date, cv_data,
    )
    ws = wb.create_sheet("Trial Balance")
    _excel_title_block(ws, building, association_id, "Trial Balance", start_date, end_date)

    headers = ["Account #", "Account Name", "Type", "Debit Balance", "Credit Balance"]
    for i, h in enumerate(headers, start=1):
        c = ws.cell(row=6, column=i, value=h)
        c.font = HEADER_FONT
        c.fill = HEADER_FILL
        c.alignment = Alignment(horizontal="center")
    row = 7

    for acct, d, c_ in tb_data["rows"]:
        ws.cell(row=row, column=1, value=acct.get("AccountNumber") or "")
        ws.cell(row=row, column=2, value=acct.get("Name") or "")
        ws.cell(row=row, column=3, value=acct.get("Type") or "")
        dc = ws.cell(row=row, column=4, value=float(d) if d else None)
        cc = ws.cell(row=row, column=5, value=float(c_) if c_ else None)
        dc.number_format = CURRENCY_FMT
        cc.number_format = CURRENCY_FMT
        row += 1

    # Totals row -- green bar across columns 3-5
    tlabel = ws.cell(row=row, column=3, value="TOTALS")
    tlabel.font = Font(bold=True, size=12, color="FFFFFF")
    tlabel.fill = SECTION_FILL
    tlabel.alignment = Alignment(horizontal="right")
    td_cell = ws.cell(row=row, column=4, value=float(tb_data["total_debit"]))
    tc_cell = ws.cell(row=row, column=5, value=float(tb_data["total_credit"]))
    for cell in (td_cell, tc_cell):
        cell.font = Font(bold=True, size=12, color="FFFFFF")
        cell.number_format = CURRENCY_FMT
        cell.fill = SECTION_FILL
    row += 2

    diff = tb_data["total_debit"] - tb_data["total_credit"]
    chk = ws.cell(
        row=row, column=3,
        value=("BALANCES ✓" if abs(diff) < Decimal("0.01") else "DOES NOT BALANCE"),
    )
    chk.font = Font(
        bold=True, size=10,
        color=("006100" if abs(diff) < Decimal("0.01") else "9C0006"),
    )
    chk.alignment = Alignment(horizontal="right")

    ws.column_dimensions["A"].width = 14
    ws.column_dimensions["B"].width = 48
    ws.column_dimensions["C"].width = 12
    ws.column_dimensions["D"].width = 18
    ws.column_dimensions["E"].width = 18
    ws.freeze_panes = "A7"

    s = wb.create_sheet("Summary")
    s["A1"] = "Daisy Living"
    s["A1"].font = Font(bold=True, size=16)
    s["A2"] = building
    s["A3"] = f"Trial Balance  |  {start_date} to {end_date}  |  Basis: {_BASIS}"
    s["A5"] = "Accounts"
    s["B5"] = len(tb_data["rows"])
    s["A6"] = "Total Debit Balances"
    s["B6"] = float(tb_data["total_debit"])
    s["B6"].number_format = CURRENCY_FMT
    s["A7"] = "Total Credit Balances"
    s["B7"] = float(tb_data["total_credit"])
    s["B7"].number_format = CURRENCY_FMT
    s["A8"] = "Difference"
    s["B8"] = float(tb_data["total_debit"] - tb_data["total_credit"])
    s["B8"].number_format = CURRENCY_FMT
    s.column_dimensions["A"].width = 26
    s.column_dimensions["B"].width = 18

    if cv_data and cv_data.get("has_variances"):
        _prepend_variance_banner(ws, num_cols=5)

    wb.save(path)


# --------------------------------------------------------------------------
# Generic tabular Excel writer (used by all 10 extended report types)
# --------------------------------------------------------------------------

def _xlsx_cell_value(value: Any, kind: str) -> Any:
    if value is None or value == "":
        return None
    if kind == "money":
        try:
            return float(value) if Decimal(str(value)) != ZERO else None
        except Exception:
            return None
    if kind == "int":
        try:
            return int(value) if int(value) != 0 else None
        except (TypeError, ValueError):
            return None
    if kind == "pct":
        try:
            return float(value)
        except (TypeError, ValueError):
            return None
    return str(value)


def write_excel_table(
    path: Path,
    building: str,
    association_id: int,
    start_date: str,
    end_date: str,
    report_title: str,
    spec: dict,
    cv_data: dict | None = None,
) -> None:
    wb = Workbook()
    cv = wb.active
    cv.title = "Cross-Validation"
    _write_cross_validation_tab(
        cv, building, association_id, report_title, start_date, end_date, cv_data,
    )
    ws = wb.create_sheet(spec.get("sheet_name") or report_title)
    columns = spec["columns"]
    rows = spec.get("rows") or []
    totals_row = spec.get("totals_row")
    notes = spec.get("notes") or []

    _excel_title_block(ws, building, association_id, report_title, start_date, end_date)

    header_row_num = 6
    if notes:
        for i, note in enumerate(notes):
            c = ws.cell(row=5 + i, column=1, value=note)
            c.font = Font(italic=True, size=9, color="808080")
        header_row_num = 6 + len(notes)

    # Column headers (hunter green)
    for i, col in enumerate(columns, start=1):
        c = ws.cell(row=header_row_num, column=i, value=col["header"])
        c.font = HEADER_FONT
        c.fill = HEADER_FILL
        c.alignment = Alignment(horizontal="center")

    row = header_row_num + 1
    for r in rows:
        for i, col in enumerate(columns, start=1):
            val = r.get(col["key"])
            cell = ws.cell(row=row, column=i, value=_xlsx_cell_value(val, col.get("kind", "text")))
            kind = col.get("kind", "text")
            if kind == "money":
                cell.number_format = CURRENCY_FMT
            elif kind == "pct":
                cell.number_format = "0.0%"
            align = col.get("align") or ("right" if kind in ("money", "int", "pct") else "left")
            cell.alignment = Alignment(horizontal=align)
        row += 1

    # Totals row — green bar across the numeric columns
    if totals_row is not None:
        # Pick the leftmost column that has a totals value
        first_total_col = None
        for i, col in enumerate(columns, start=1):
            if col["key"] in totals_row:
                first_total_col = i
                break
        label_col = max(1, (first_total_col or len(columns)) - 1)
        label_cell = ws.cell(row=row, column=label_col, value="TOTAL")
        label_cell.font = SECTION_FONT
        label_cell.fill = SECTION_FILL
        label_cell.alignment = Alignment(horizontal="right")
        # Fill label_col through end with section fill for a continuous bar
        for i in range(label_col + 1, len(columns) + 1):
            col = columns[i - 1]
            cell = ws.cell(row=row, column=i)
            cell.fill = SECTION_FILL
            cell.font = SECTION_FONT
            key = col["key"]
            if key in totals_row:
                val = totals_row[key]
                cell.value = _xlsx_cell_value(val, col.get("kind", "text"))
                kind = col.get("kind", "text")
                if kind == "money":
                    cell.number_format = CURRENCY_FMT
                elif kind == "pct":
                    cell.number_format = "0.0%"
            cell.alignment = Alignment(horizontal="right")
        row += 2

    # Column widths
    for i, col in enumerate(columns, start=1):
        ws.column_dimensions[get_column_letter(i)].width = col.get("width", 14)

    ws.freeze_panes = ws.cell(row=header_row_num + 1, column=1).coordinate

    # Summary tab
    summary = spec.get("summary") or []
    if summary:
        s = wb.create_sheet("Summary")
        s["A1"] = "Daisy Living"
        s["A1"].font = Font(bold=True, size=16)
        s["A2"] = building
        s["A3"] = f"{report_title}  |  {start_date} to {end_date}  |  Basis: {_BASIS}"
        for i, (label, value, kind) in enumerate(summary, start=5):
            s.cell(row=i, column=1, value=label)
            c = s.cell(row=i, column=2, value=_xlsx_cell_value(value, kind))
            if kind == "money":
                c.number_format = CURRENCY_FMT
            elif kind == "pct":
                c.number_format = "0.0%"
        s.column_dimensions["A"].width = 28
        s.column_dimensions["B"].width = 18

    if cv_data and cv_data.get("has_variances"):
        _prepend_variance_banner(ws, num_cols=len(columns))

    wb.save(path)


_REPORT_DISPLAY_NAMES: dict[str, str] = {
    "general_ledger":         "General Ledger",
    "income_statement":       "Income Statement",
    "balance_sheet":          "Balance Sheet",
    "trial_balance":          "Trial Balance",
    "ap_aging":               "AP Aging",
    "ar_aging":               "AR Aging",
    "budget_vs_actual":       "Budget vs Actual",
    "check_register":         "Check Register",
    "rent_roll":              "Rent Roll",
    "owner_statement":        "Owner Statement",
    "vendor_payment_summary": "Vendor Payment Summary",
    "bank_register":          "Bank Register",
    "deposit_detail":         "Deposit Detail",
    "board_roster":           "Board Roster",
}


def _summary_cell_value(value: Any, kind: str) -> Any:
    """
    Like `_xlsx_cell_value` but preserves zero, because in a summary row
    'Total 0' and 'Net 0' are meaningful answers — not empty cells.
    """
    if value is None or value == "":
        return None
    if kind == "money":
        try:
            return float(value)
        except Exception:
            return None
    if kind == "int":
        try:
            return int(value)
        except (TypeError, ValueError):
            return None
    if kind == "pct":
        try:
            return float(value)
        except (TypeError, ValueError):
            return None
    return str(value)


def write_combined_summary_workbook(
    path: Path,
    building: str,
    association_id: int,
    start_date: str,
    end_date: str,
    results: list[dict],
) -> None:
    """
    Build the combined summary workbook that `--report-type all` emits.

    Layout:
      - Overview tab: one row per report with run status, key metric, and
        a pointer to its per-report xlsx/pdf filenames.
      - One tab per successful report, echoing the Summary fields
        (label / value / kind) the report's own builder produced.

    `results` is a list of per-report dicts produced by the `all`-mode
    runner. Each dict looks like:
        {
            "report_type": "general_ledger",
            "ok": True,
            "xlsx": "/path/to/file.xlsx",
            "pdf":  "/path/to/file.pdf",
            "summary": [(label, value, kind), ...],
        }
    On error the dict has ok=False and error=<str>.
    """
    wb = Workbook()

    # --- Overview tab ---
    overview = wb.active
    overview.title = "Overview"
    _excel_title_block(
        overview, building, association_id,
        "All Reports Summary", start_date, end_date,
    )

    headers_row = ["Report", "Status", "Cross-Validation", "Key Metric", "Value", "Excel", "PDF"]
    for i, h in enumerate(headers_row, start=1):
        c = overview.cell(row=6, column=i, value=h)
        c.font = HEADER_FONT
        c.fill = HEADER_FILL
        c.alignment = Alignment(horizontal="center")

    row = 7
    for result in results:
        rt = result.get("report_type", "?")
        overview.cell(row=row, column=1, value=_REPORT_DISPLAY_NAMES.get(rt, rt))

        if result.get("ok"):
            overview.cell(row=row, column=2, value="OK")
        else:
            err = (result.get("error") or "error")[:80]
            c = overview.cell(row=row, column=2, value=f"FAIL: {err}")
            c.font = Font(bold=True, color="9C0006")

        # Cross-validation status column
        cv_rows = int(result.get("cv_row_count") or 0)
        cv_mm = int(result.get("cv_mismatch_count") or 0)
        if cv_rows == 0:
            cv_text = "—"
            cv_cell = overview.cell(row=row, column=3, value=cv_text)
            cv_cell.font = Font(italic=True, color="808080")
        elif cv_mm == 0:
            cv_cell = overview.cell(row=row, column=3, value=f"OK ({cv_rows})")
            cv_cell.font = Font(bold=True, color=MATCH_COLOR)
        else:
            cv_cell = overview.cell(row=row, column=3, value=f"VARIANCE ({cv_mm}/{cv_rows})")
            cv_cell.font = Font(bold=True, color=MISMATCH_COLOR)
        cv_cell.alignment = Alignment(horizontal="center")

        # Pick the most interesting metric as the "key metric": first money
        # entry in the summary, falling back to the first int entry.
        summary = result.get("summary") or []
        key_metric = None
        for label, value, kind in summary:
            if kind == "money":
                key_metric = (label, value, "money")
                break
        if key_metric is None:
            for label, value, kind in summary:
                if kind == "int":
                    key_metric = (label, value, "int")
                    break
        if key_metric:
            overview.cell(row=row, column=4, value=key_metric[0])
            c = overview.cell(
                row=row, column=5,
                value=_summary_cell_value(key_metric[1], key_metric[2]),
            )
            if key_metric[2] == "money":
                c.number_format = CURRENCY_FMT

        # Excel and PDF filenames
        if result.get("xlsx"):
            overview.cell(row=row, column=6, value=Path(result["xlsx"]).name)
        if result.get("pdf"):
            overview.cell(row=row, column=7, value=Path(result["pdf"]).name)

        row += 1

    # Totals row at the bottom — count successful / failed / variances
    n_ok = sum(1 for r in results if r.get("ok"))
    n_fail = len(results) - n_ok
    n_cv_var = sum(1 for r in results if r.get("cv_has_variances"))
    row += 1
    label_cell = overview.cell(
        row=row, column=1,
        value=f"{n_ok} succeeded, {n_fail} failed, {n_cv_var} with CV variances",
    )
    label_cell.font = SECTION_FONT
    label_cell.fill = SECTION_FILL
    for col in range(2, len(headers_row) + 1):
        overview.cell(row=row, column=col).fill = SECTION_FILL

    overview.column_dimensions["A"].width = 24
    overview.column_dimensions["B"].width = 14
    overview.column_dimensions["C"].width = 18
    overview.column_dimensions["D"].width = 24
    overview.column_dimensions["E"].width = 18
    overview.column_dimensions["F"].width = 60
    overview.column_dimensions["G"].width = 60
    overview.freeze_panes = "A7"

    # --- One tab per successful report with its summary fields ---
    for result in results:
        if not result.get("ok"):
            continue
        rt = result.get("report_type", "?")
        pretty_title = _REPORT_DISPLAY_NAMES.get(rt, rt)
        # Excel tab names are capped at 31 chars and can't include /\?*[]
        tab_name = pretty_title[:31]
        ws = wb.create_sheet(tab_name)
        _excel_title_block(
            ws, building, association_id, pretty_title, start_date, end_date,
        )

        # Header for the key/value table
        h1 = ws.cell(row=6, column=1, value="Metric")
        h2 = ws.cell(row=6, column=2, value="Value")
        for c in (h1, h2):
            c.font = HEADER_FONT
            c.fill = HEADER_FILL
            c.alignment = Alignment(horizontal="center")

        row = 7
        for label, value, kind in (result.get("summary") or []):
            ws.cell(row=row, column=1, value=label)
            c = ws.cell(row=row, column=2, value=_summary_cell_value(value, kind))
            if kind == "money":
                c.number_format = CURRENCY_FMT
            elif kind == "pct":
                c.number_format = "0.0%"
            row += 1

        # File pointers (bottom of tab)
        row += 1
        if result.get("xlsx"):
            ws.cell(row=row, column=1, value="Excel file").font = Font(italic=True, size=9)
            ws.cell(row=row, column=2, value=Path(result["xlsx"]).name).font = Font(italic=True, size=9)
            row += 1
        if result.get("pdf"):
            ws.cell(row=row, column=1, value="PDF file").font = Font(italic=True, size=9)
            ws.cell(row=row, column=2, value=Path(result["pdf"]).name).font = Font(italic=True, size=9)

        ws.column_dimensions["A"].width = 30
        ws.column_dimensions["B"].width = 24

    wb.save(path)


# --------------------------------------------------------------------------
# PDF output
# --------------------------------------------------------------------------

def _fmt_money(d: Decimal) -> str:
    if d is None or d == ZERO:
        return ""
    sign = "-" if d < 0 else ""
    n = abs(d).quantize(Decimal("0.01"))
    # Thousands separator
    whole, frac = str(n).split(".")
    whole_with_commas = f"{int(whole):,}"
    return f"{sign}${whole_with_commas}.{frac}"


def _fmt_money_always(d: Decimal) -> str:
    s = _fmt_money(d)
    return s or "$0.00"


def write_pdf_gl(
    path: Path,
    building: str,
    association_id: int,
    start_date: str,
    end_date: str,
    groups: list[tuple[dict, list[dict], Decimal, Decimal]],
    total_debit: Decimal,
    total_credit: Decimal,
) -> None:
    doc = SimpleDocTemplate(
        str(path),
        pagesize=landscape(letter),
        leftMargin=0.4 * inch,
        rightMargin=0.4 * inch,
        topMargin=0.5 * inch,
        bottomMargin=0.5 * inch,
        title=f"{building} - General Ledger",
    )

    styles = getSampleStyleSheet()
    story = _pdf_header_story(
        building, association_id, "General Ledger", start_date, end_date,
    )

    header_row = ["Date", "Txn Type", "Txn ID", "Memo", "Debit", "Credit", "Balance"]
    col_widths = [0.8 * inch, 1.0 * inch, 0.7 * inch, 4.6 * inch, 1.0 * inch, 1.0 * inch, 1.1 * inch]

    base_style = TableStyle([
        ("FONTNAME", (0, 0), (-1, 0), "Helvetica-Bold"),
        ("FONTSIZE", (0, 0), (-1, -1), 8),
        ("BACKGROUND", (0, 0), (-1, 0), colors.HexColor(DAISY_GREEN)),
        ("TEXTCOLOR", (0, 0), (-1, 0), colors.white),
        ("ALIGN", (4, 0), (-1, -1), "RIGHT"),
        ("ALIGN", (0, 0), (-1, 0), "CENTER"),
        ("GRID", (0, 0), (-1, -1), 0.25, colors.grey),
        ("VALIGN", (0, 0), (-1, -1), "MIDDLE"),
        ("LEFTPADDING", (0, 0), (-1, -1), 3),
        ("RIGHTPADDING", (0, 0), (-1, -1), 3),
    ])

    for acct, lines, td, tc in groups:
        section = Paragraph(
            f"<b><font color='{DAISY_GREEN}'>"
            f"{acct.get('AccountNumber','')} &nbsp; {acct.get('Name','')}"
            f"</font></b> "
            f"<font color='grey' size='8'>({acct.get('Type','')})</font>",
            styles["Normal"],
        )
        story.append(Spacer(1, 0.08 * inch))
        story.append(section)

        data = [header_row]
        balance = ZERO
        for line in lines:
            balance += line["debit"] - line["credit"]
            memo = (str(line["memo"]) or "")[:180]
            data.append([
                line["date"],
                line["txn_type"],
                str(line["txn_id"] or ""),
                memo,
                _fmt_money(line["debit"]),
                _fmt_money(line["credit"]),
                _fmt_money_always(balance),
            ])
        data.append(["", "", "", "Subtotal:", _fmt_money_always(td), _fmt_money_always(tc), _fmt_money_always(td - tc)])

        t = Table(data, colWidths=col_widths, repeatRows=1)
        style = TableStyle(base_style.getCommands())
        # alternating row shading (Daisy cream)
        for i in range(1, len(data) - 1):
            if i % 2 == 0:
                style.add("BACKGROUND", (0, i), (-1, i), colors.HexColor(DAISY_CREAM))
        # subtotal row: hunter green background, white text, bold
        style.add("FONTNAME", (0, -1), (-1, -1), "Helvetica-Bold")
        style.add("BACKGROUND", (0, -1), (-1, -1), colors.HexColor(DAISY_GREEN))
        style.add("TEXTCOLOR", (0, -1), (-1, -1), colors.white)
        t.setStyle(style)
        story.append(t)

    # Grand total
    story.append(Spacer(1, 0.2 * inch))
    gt = Table(
        [["GRAND TOTAL", _fmt_money_always(total_debit), _fmt_money_always(total_credit), _fmt_money_always(total_debit - total_credit)]],
        colWidths=[7.1 * inch, 1.0 * inch, 1.0 * inch, 1.1 * inch],
    )
    gt.setStyle(TableStyle([
        ("FONTNAME", (0, 0), (-1, -1), "Helvetica-Bold"),
        ("FONTSIZE", (0, 0), (-1, -1), 10),
        ("ALIGN", (0, 0), (0, 0), "RIGHT"),
        ("ALIGN", (1, 0), (-1, -1), "RIGHT"),
        ("BACKGROUND", (0, 0), (-1, -1), colors.HexColor(DAISY_GREEN)),
        ("TEXTCOLOR", (0, 0), (-1, -1), colors.white),
        ("BOX", (0, 0), (-1, -1), 1, colors.black),
        ("LEFTPADDING", (0, 0), (-1, -1), 6),
        ("RIGHTPADDING", (0, 0), (-1, -1), 6),
        ("TOPPADDING", (0, 0), (-1, -1), 6),
        ("BOTTOMPADDING", (0, 0), (-1, -1), 6),
    ]))
    story.append(gt)

    def on_page(canvas, doc_):
        canvas.saveState()
        canvas.setFont("Helvetica", 8)
        canvas.setFillColor(colors.grey)
        canvas.drawRightString(
            landscape(letter)[0] - 0.4 * inch,
            0.3 * inch,
            f"Page {doc_.page}",
        )
        canvas.restoreState()

    doc.build(story, onFirstPage=on_page, onLaterPages=on_page)


def _daisy_logo_flowable(max_height_in: float = 0.55) -> Image | None:
    """Return a reportlab Image flowable for the Daisy logo, sized to the
    given max height in inches. Returns None if the logo file is missing."""
    if not DAISY_LOGO_PATH.exists():
        return None
    # Logo source aspect is ~2.5:1 (2542 x 1017 pixels).
    src_w, src_h = 2542.0, 1017.0
    h = max_height_in * inch
    w = h * (src_w / src_h)
    img = Image(str(DAISY_LOGO_PATH), width=w, height=h)
    img.hAlign = "LEFT"
    return img


def _pdf_header_story(
    building: str, association_id: int, report_title: str,
    start_date: str, end_date: str, note: str | None = None,
) -> list:
    styles = getSampleStyleSheet()
    h2 = ParagraphStyle(
        "h2", parent=styles["Heading2"], fontSize=13, spaceAfter=2,
        textColor=colors.HexColor(DAISY_GREEN),
    )
    meta = ParagraphStyle(
        "meta", parent=styles["Normal"], fontSize=8, textColor=colors.grey,
    )
    story: list = []
    logo = _daisy_logo_flowable()
    if logo is not None:
        story.append(logo)
        story.append(Spacer(1, 0.08 * inch))
    else:
        # Fallback: text branding if the logo file is missing.
        h1 = ParagraphStyle(
            "h1", parent=styles["Heading1"], fontSize=18, spaceAfter=2,
            textColor=colors.HexColor(DAISY_GREEN),
        )
        story.append(Paragraph("daisy", h1))
    story.extend([
        Paragraph(building, h2),
        Paragraph(
            f"{report_title} &nbsp;|&nbsp; {start_date} to {end_date} "
            f"&nbsp;|&nbsp; <b>Basis: {_BASIS}</b>",
            styles["Normal"],
        ),
        Paragraph(
            f"Association ID: {association_id} &nbsp;|&nbsp; "
            f"Generated: {datetime.now():%Y-%m-%d %H:%M}",
            meta,
        ),
    ])
    if note:
        story.append(Paragraph(f"<i>{note}</i>", meta))
    story.append(Spacer(1, 0.15 * inch))
    return story


def _pdf_on_page_portrait(canvas, doc_):
    canvas.saveState()
    canvas.setFont("Helvetica", 8)
    canvas.setFillColor(colors.grey)
    canvas.drawRightString(letter[0] - 0.6 * inch, 0.3 * inch, f"Page {doc_.page}")
    canvas.restoreState()


def write_pdf_is(
    path: Path,
    building: str,
    association_id: int,
    start_date: str,
    end_date: str,
    is_data: dict,
) -> None:
    doc = SimpleDocTemplate(
        str(path), pagesize=letter,
        leftMargin=0.6 * inch, rightMargin=0.6 * inch,
        topMargin=0.6 * inch, bottomMargin=0.6 * inch,
        title=f"{building} - Income Statement",
    )
    styles = getSampleStyleSheet()
    sec_style = ParagraphStyle(
        "sec", parent=styles["Heading3"], fontSize=12,
        textColor=colors.HexColor(DAISY_GREEN), spaceBefore=10, spaceAfter=4,
    )
    story = _pdf_header_story(building, association_id, "Income Statement", start_date, end_date)
    col_widths = [1.0 * inch, 4.8 * inch, 1.5 * inch]

    def section(title: str, rows: list[tuple[dict, Decimal]], total_label: str, total_val: Decimal) -> None:
        story.append(Paragraph(f"<b>{title}</b>", sec_style))
        data = [[
            str(a.get("AccountNumber") or ""),
            str(a.get("Name") or ""),
            _fmt_money_always(amt),
        ] for a, amt in rows]
        data.append(["", total_label, _fmt_money_always(total_val)])
        t = Table(data, colWidths=col_widths)
        style = TableStyle([
            ("FONTSIZE", (0, 0), (-1, -1), 9),
            ("ALIGN", (2, 0), (2, -1), "RIGHT"),
            ("BOTTOMPADDING", (0, 0), (-1, -1), 3),
            ("TOPPADDING", (0, 0), (-1, -1), 3),
            ("LEFTPADDING", (0, 0), (-1, -1), 4),
            ("RIGHTPADDING", (0, 0), (-1, -1), 4),
        ])
        for i in range(len(data) - 1):
            if i % 2 == 1:
                style.add("BACKGROUND", (0, i), (-1, i), colors.HexColor(DAISY_CREAM))
        style.add("FONTNAME", (0, -1), (-1, -1), "Helvetica-Bold")
        style.add("LINEABOVE", (0, -1), (-1, -1), 0.75, colors.black)
        style.add("BACKGROUND", (0, -1), (-1, -1), colors.HexColor(DAISY_GREEN))
        style.add("TEXTCOLOR", (0, -1), (-1, -1), colors.white)
        t.setStyle(style)
        story.append(t)

    section("REVENUE", is_data["revenue"], "Total Revenue", is_data["total_revenue"])
    section("EXPENSES", is_data["expenses"], "Total Expenses", is_data["total_expenses"])

    story.append(Spacer(1, 0.2 * inch))
    nt = Table(
        [["NET INCOME", _fmt_money_always(is_data["net_income"])]],
        colWidths=[5.8 * inch, 1.5 * inch],
    )
    nt.setStyle(TableStyle([
        ("FONTNAME", (0, 0), (-1, -1), "Helvetica-Bold"),
        ("FONTSIZE", (0, 0), (-1, -1), 12),
        ("ALIGN", (0, 0), (0, 0), "RIGHT"),
        ("ALIGN", (1, 0), (-1, -1), "RIGHT"),
        ("BACKGROUND", (0, 0), (-1, -1), colors.HexColor(DAISY_GREEN)),
        ("TEXTCOLOR", (0, 0), (-1, -1), colors.white),
        ("BOX", (0, 0), (-1, -1), 1, colors.black),
        ("LEFTPADDING", (0, 0), (-1, -1), 8),
        ("RIGHTPADDING", (0, 0), (-1, -1), 8),
        ("TOPPADDING", (0, 0), (-1, -1), 6),
        ("BOTTOMPADDING", (0, 0), (-1, -1), 6),
    ]))
    story.append(nt)
    doc.build(story, onFirstPage=_pdf_on_page_portrait, onLaterPages=_pdf_on_page_portrait)


def write_pdf_bs(
    path: Path,
    building: str,
    association_id: int,
    start_date: str,
    end_date: str,
    bs_data: dict,
) -> None:
    doc = SimpleDocTemplate(
        str(path), pagesize=letter,
        leftMargin=0.6 * inch, rightMargin=0.6 * inch,
        topMargin=0.6 * inch, bottomMargin=0.6 * inch,
        title=f"{building} - Balance Sheet",
    )
    styles = getSampleStyleSheet()
    sec_style = ParagraphStyle(
        "sec", parent=styles["Heading3"], fontSize=13,
        textColor=colors.HexColor(DAISY_GREEN), spaceBefore=10, spaceAfter=4,
    )
    sub_style = ParagraphStyle(
        "sub", parent=styles["Normal"], fontSize=10,
        textColor=colors.black, spaceBefore=4, spaceAfter=2, leftIndent=10,
    )
    story = _pdf_header_story(
        building, association_id, "Balance Sheet", start_date, end_date,
        note="Period activity only — opening balances assumed $0 on start date",
    )
    col_widths = [1.0 * inch, 4.8 * inch, 1.5 * inch]
    base_style_cmds = [
        ("FONTSIZE", (0, 0), (-1, -1), 9),
        ("ALIGN", (2, 0), (2, -1), "RIGHT"),
        ("BOTTOMPADDING", (0, 0), (-1, -1), 2),
        ("TOPPADDING", (0, 0), (-1, -1), 2),
        ("LEFTPADDING", (0, 0), (-1, -1), 4),
        ("RIGHTPADDING", (0, 0), (-1, -1), 4),
    ]

    def section(title: str, section_data: dict, total_label: str, total_val: Decimal) -> None:
        story.append(Paragraph(f"<b>{title}</b>", sec_style))
        for sub, rows_ in section_data.items():
            story.append(Paragraph(f"<b><i>{sub}</i></b>", sub_style))
            data = [[
                str(a.get("AccountNumber") or ""),
                str(a.get("Name") or ""),
                _fmt_money_always(amt),
            ] for a, amt in rows_]
            sub_total = sum((r[1] for r in rows_), ZERO)
            data.append(["", f"Subtotal - {sub}", _fmt_money_always(sub_total)])
            t = Table(data, colWidths=col_widths)
            style = TableStyle(list(base_style_cmds))
            for i in range(len(data) - 1):
                if i % 2 == 1:
                    style.add("BACKGROUND", (0, i), (-1, i), colors.HexColor(DAISY_CREAM))
            style.add("FONTNAME", (0, -1), (-1, -1), "Helvetica-BoldOblique")
            style.add("LINEABOVE", (0, -1), (-1, -1), 0.4, colors.grey)
            t.setStyle(style)
            story.append(t)
        # Section total
        story.append(Spacer(1, 0.05 * inch))
        tt = Table([["", total_label, _fmt_money_always(total_val)]], colWidths=col_widths)
        tt.setStyle(TableStyle([
            ("FONTNAME", (0, 0), (-1, -1), "Helvetica-Bold"),
            ("FONTSIZE", (0, 0), (-1, -1), 10),
            ("ALIGN", (2, 0), (-1, -1), "RIGHT"),
            ("BACKGROUND", (0, 0), (-1, -1), colors.HexColor(DAISY_GREEN)),
            ("TEXTCOLOR", (0, 0), (-1, -1), colors.white),
            ("LINEABOVE", (0, 0), (-1, -1), 1, colors.black),
        ]))
        story.append(tt)

    section("ASSETS", bs_data["assets"], "TOTAL ASSETS", bs_data["total_assets"])
    section("LIABILITIES", bs_data["liabilities"], "Total Liabilities", bs_data["total_liabilities"])
    section("EQUITY", bs_data["equity"], "Total Equity", bs_data["total_equity"])

    story.append(Spacer(1, 0.2 * inch))
    lpe = Table(
        [["TOTAL LIABILITIES + EQUITY", _fmt_money_always(bs_data["liab_plus_equity"])]],
        colWidths=[5.8 * inch, 1.5 * inch],
    )
    lpe.setStyle(TableStyle([
        ("FONTNAME", (0, 0), (-1, -1), "Helvetica-Bold"),
        ("FONTSIZE", (0, 0), (-1, -1), 11),
        ("ALIGN", (0, 0), (0, 0), "RIGHT"),
        ("ALIGN", (1, 0), (-1, -1), "RIGHT"),
        ("BACKGROUND", (0, 0), (-1, -1), colors.HexColor(DAISY_GREEN)),
        ("TEXTCOLOR", (0, 0), (-1, -1), colors.white),
        ("BOX", (0, 0), (-1, -1), 1, colors.black),
        ("LEFTPADDING", (0, 0), (-1, -1), 8),
        ("RIGHTPADDING", (0, 0), (-1, -1), 8),
        ("TOPPADDING", (0, 0), (-1, -1), 6),
        ("BOTTOMPADDING", (0, 0), (-1, -1), 6),
    ]))
    story.append(lpe)

    story.append(Spacer(1, 0.1 * inch))
    delta = bs_data["total_assets"] - bs_data["liab_plus_equity"]
    balance_ok = bs_data["balances"]
    chk_text = "BALANCES (Assets = Liabilities + Equity)" if balance_ok else "DOES NOT BALANCE"
    chk_color = colors.HexColor("#006100") if balance_ok else colors.HexColor("#9C0006")
    chk = Table(
        [[chk_text, _fmt_money_always(delta)]],
        colWidths=[5.8 * inch, 1.5 * inch],
    )
    chk.setStyle(TableStyle([
        ("FONTNAME", (0, 0), (-1, -1), "Helvetica-Bold"),
        ("FONTSIZE", (0, 0), (-1, -1), 9),
        ("TEXTCOLOR", (0, 0), (-1, -1), chk_color),
        ("ALIGN", (0, 0), (0, 0), "RIGHT"),
        ("ALIGN", (1, 0), (-1, -1), "RIGHT"),
    ]))
    story.append(chk)

    doc.build(story, onFirstPage=_pdf_on_page_portrait, onLaterPages=_pdf_on_page_portrait)


